":"26","previousNodeOutput":0,"previousNodeRun":0},{"message":"56","location":"57"},["58"],{"previousNode":"59","previousNodeOutput":0,"previousNodeRun":0},["60"],{"previousNode":"61","previousNodeOutput":0,"previousNodeRun":0},["62"],{"previousNode":"63","previousNodeOutput":0,"previousNodeRun":0},["64"],["65"],"To split the contents of ‘data’ into separate items for easier processing, add a ‘Split Out’ node after this one","outputPane",["66"],"Get digest_mails rows",["67"],"Build digest text",["68"],"Send digest to Telegram",["69"],{"json":"70","pairedItem":"71"},{"json":"72","pairedItem":"73"},{"json":"74","pairedItem":"75"},{"json":"76","pairedItem":"77"},{"json":"78","pairedItem":"79"},{"timestamp":"80","Readable date":"81","Readable time":"82","Day of week":"83","Year":"84","Month":"85","Day of month":"86","Hour":"87","Minute":"88","Second":"88","Timezone":"89"},{"item":0},{"data":"90","nextCursor":null},{"item":0},{"text":"91","count":11},{"item":0},{"ok":true,"result":"92"},{"item":0},{"deletedCount":11},{"item":0},"2026-10-29T07:00:00.053+01:00","October 29th 2026, 7:00:00 am","7:00:00 am","Thursday","2026","October","29","07","00","Europe/Paris (UTC+01:00)",["93","94","95","96","97","98","99","100","101","102","103"],"📋 Digest quotidien EBANISTA — 11 mail(s)\\n\\n📥 v.caufriez@ebanista.fr (3)\\n\\n• [suivi_client] \\"IGNACIO Richard\\" <richard.ignacio@edf.fr>\\n  Richard Ignacio (EDF) répond à la proposition de créneaux d'UniTech/EBANISTA pour une réunion de clarifications techniques sur les conteneurs EDF AMT VDR. Il indique que le 04/11 à 8h semble convenir, confirmation à venir dans l'après-midi. Valentin est mentionné comme aménageur EBANISTA impliqué dans le projet.\\n\\n• [suivi_client] \\"VEKEMANS Jeanne\\" <jeanne.vekemans@gerflor.com>\\n  Gerflor transfère le suivi des panneaux Virtuo pour Maldegem à Christine Norde. Valentin est invité à lui envoyer des photos et à expédier les panneaux finis à Frédérique Bourdin (service échantillon Gerflor Saint Paul).\\n\\n• [confirmation_commande] \\"Rodrigue Pons\\" <Rodrigue-Pons@cica-bois.fr>\\n  AR de commande n°3731754 pour de l'avivé chêne reçu du fournisseur CICA Bois. Livraison confirmée à l'adresse d'EBANISTA à Valaurie. Contacter le fournisseur avant 10h si l'adresse est incorrecte.\\n\\n📥 contact@ebanista.fr (6)\\n\\n• [suivi_client] \\"BCNLED Commercial France\\" <commercial@barcelonaled.fr>\\n  BCNLED confirme la réception de la demande de retour pour la commande 68631 et fournit une étiquette Mondial Relay. Le remboursement sera effectué après réception et contrôle. De nouveaux accès professionnels seront envoyés sous peu.\\n\\n• [offre_fournisseur] \\"BCNLED Commercial France\\" <commercialfrance@bcnled.com>\\n  Barcelona LED reprend contact pour faire évoluer le partenariat commercial, présente de nouvelles grilles tarifaires accessibles sur leur plateforme B2B et demande si EBANISTA a des projets en cours.\\n\\n• [prospects] \\"Marie-Claude Paillon\\" <mc_paillon@yahoo.fr>\\n  Marie-Claude Paillon, prospect recommandé par Mme Valette (Cap Habitat), répond à un premier échange et souhaite un contact téléphonique pour discuter de son projet.\\n\\n• [administratif] \\"TotalEnergies Electricité et Gaz\\" <service.client@mails.totalenergies.fr>\\n  Bilan mensuel de consommation électrique TotalEnergies pour le 21 rue Antoine Becquerel, Valaurie. 698 kWh consommés du 25/09 au 25/10, en baisse de 7% par rapport à septembre 2025.\\n\\n• [prospects] \\"Marie-Claude Paillon\\" <mc_paillon@yahoo.fr>\\n  Mme Paillon transmet les plans de ses placards/dressing à aménager (cellier au-dessus lave-linge, dressing élargi de 20 cm) et propose un rendez-vous sur site la semaine prochaine.\\n\\n• [confirmation_commande] \\"Barcelona Led\\" <sales@bcnled.com>\\n  Confirmation de la commande n°71678 passée auprès de Barcelona Led (spots LED, projecteur, rails magnétiques) pour un total de 371,87€. La commande est en cours de préparation pour expédition via GLS.\\n\\n📥 comptabilite@ebanista.fr (2)\\n\\n• [offre_fournisseur] \\"Rodrigue Pons\\" <Rodrigue-Pons@cica-bois.fr>\\n  Devis n°3731709 reçu du fournisseur CICA Bois (bois massifs, carrelets, terrasses) en pièce jointe au format PDF.\\n\\n• [administratif] \\"TotalEnergies Electricité et Gaz\\" <service.client@mails.totalenergies.fr>\\n  Bilan mensuel de consommation électrique de TotalEnergies pour l'adresse du 21 rue Antoine Becquerel, Valaurie. Consommation de 59 kWh du 25/09 au 25/10, en hausse de 111% par rapport à septembre 2025.",{"message_id":182,"from":"104","chat":"105","date":1793253600,"text":"91","entities":"106"},{"date":"107","expediteur":"108","categorie":"109","resume":"110","auto_envoye":false,"boite":null,"id":369,"createdAt":"111","updatedAt":"111"},{"date":"112","expediteur":"113","categorie":"109","resume":"114","auto_envoye":false,"boite":"115","id":370,"createdAt":"116","updatedAt":"116"},{"date":"117","expediteur":"118","categorie":"119","resume":"120","auto_envoye":false,"boite":"115","id":371,"createdAt":"121","updatedAt":"121"},{"date":"122","expediteur":"123","categorie":"109","resume":"124","auto_envoye":false,"boite":null,"id":372,"createdAt":"125","updatedAt":"125"},{"date":"126","expediteur":"127","categorie":"119","resume":"128","auto_envoye":false,"boite":"129","id":373,"createdAt":"130","updatedAt":"130"},{"date":"131","expediteur":"127","categorie":"132","resume":"133","auto_envoye":true,"boite":null,"id":374,"createdAt":"134","updatedAt":"134"},{"date":"135","expediteur":"136","categorie":"137","resume":"138","auto_envoye":false,"boite":"115","id":375,"createdAt":"139","updatedAt":"139"},{"date":"140","expediteur":"141","categorie":"142","resume":"143","auto_envoye":false,"boite":"129","id":376,"createdAt":"144","updatedAt":"144"},{"date":"140","expediteur":"141","categorie":"142","resume":"145","auto_envoye":false,"boite":"115","id":377,"createdAt":"146","updatedAt":"146"},{"date":"147","expediteur":"136","categorie":"137","resume":"148","auto_