-collapse: collapse; border-spacing: 0px;\\">\\n<tbody>\\n<tr>\\n<td style=\\"direction: ltr; text-indent: 0px;\\">\\n<table role=\\"presentation\\" cellspacing=\\"0\\" cellpadding=\\"0\\" border=\\"0\\" style=\\"direction: ltr; text-indent: 0px; width: 100%; box-sizing: border-box; border-collapse: collapse; border-spacing: 0px;\\">\\n<tbody>\\n<tr>\\n<th style=\\"direction: ltr; text-align: left; text-indent: 0px; vertical-align: top; width: 100%;\\">\\n<table align=\\"center\\" role=\\"presentation\\" cellspacing=\\"0\\" cellpadding=\\"0\\" border=\\"0\\" style=\\"direction: ltr; text-indent: 0px; width: 600px; table-layout: fixed; box-sizing: border-box; border-collapse: collapse; border-spacing: 0px;\\">\\n<tbody>\\n<tr>\\n<td style=\\"direction: ltr; text-indent: 0px; line-height: 20px; height: 20px;\\">\\n<div style=\\"direction: ltr; text-indent: 0px; line-height: 20px; font-family: Times; font-size: 20px; color: rgb(65, 65, 65);\\">\\n<span style=\\"font-weight: normal;\\">­</span></div>\\n</td>\\n</tr>\\n</tbody>\\n</table>\\n</th>\\n</tr>\\n</tbody>\\n</table>\\n</td>\\n</tr>\\n</tbody>\\n</table>\\n</td>\\n</tr>\\n</tbody>\\n</table>\\n<div style=\\"direction: ltr; text-indent: 0px; font-family: Times; font-size: 14px;\\">\\n<br>\\n</div>\\n<div style=\\"direction: ltr; font-family: Helvetica; font-size: 14px;\\"><br>\\n<br>\\n<br>\\n<br>\\n</div>\\n<div style=\\"text-indent: 0px; font-family: Helvetica; font-size: 14px;\\"><br>\\n</div>\\n<blockquote>\\n<div style=\\"text-indent: 0px; font-family: Helvetica; font-size: 14px;\\">Le 7 oct. 2026 à 12:02, L. Sauzade - UniTech &lt;lsauzade@unitecheu.com&gt; a écrit :</div>\\n<div style=\\"font-family: Helvetica; font-size: 14px;\\"><br>\\n</div>\\n<div style=\\"text-indent: 0px; font-family: &quot;Trebuchet MS&quot;, Trebuchet, sans-serif; font-size: 11pt;\\">\\nSalut Stéphane,</div>\\n<div style=\\"text-indent: 0px; font-family: &quot;Trebuchet MS&quot;, Trebuchet, sans-serif; font-size: 11pt;\\">\\n<br>\\n</div>\\n<div style=\\"text-indent: 0px; font-family: &quot;Trebuchet MS&quot;, Trebuchet, sans-serif; font-size: 11pt;\\">\\n<br>\\n</div>\\n<div style=\\"text-indent: 0px; font-family: &quot;Trebuchet MS&quot;, Trebuchet, sans-serif; font-size: 11pt;\\">\\nDésolée pour ma réponse tardive, j'étais en formation CST.</div>\\n<div style=\\"text-indent: 0px; font-family: &quot;Trebuchet MS&quot;, Trebuchet, sans-serif; font-size: 11pt;\\">\\nNon, pas d'élec, le plus gros de l'aménagement sera fait par un autre aménageur.</div>\\n<div style=\\"text-indent: 0px; font-family: &quot;Trebuchet MS&quot;, Trebuchet, sans-serif; font-size: 11pt;\\">\\n<br>\\n</div>\\n<div style=\\"text-indent: 0px; font-family: &quot;Trebuchet MS&quot;, Trebuchet, sans-serif; font-size: 11pt;\\">\\n<br>\\n</div>\\n<div id=\\"x_x_x_x_x_Signature\\">\\n<div style=\\"text-indent: 0px; font-family: &quot;Trebuchet MS&quot;, Trebuchet, sans-serif; font-size: 11pt;\\">\\n<br>\\n</div>\\n<div style=\\"text-align: justify; text-indent: 0px; background-color: white; margin: 0px; font-family: &quot;Trebuchet MS&quot;, Trebuchet, sans-serif; font-size: 11pt; color: rgb(200, 38, 19);\\">\\n<b><i>LVNF Nuclear &amp; Logistic Consulting devient UniTech Services à compter du 1er septembre 2026. Nos interlocuteurs et prestations restent inchangés ; seule notre entité et notre adresse e-mail évoluent.</i></b></div>\\n<div style=\\"text-align: left; text-indent: 0px; background-color: white; margin: 0px; font-family: &quot;Trebuchet MS&quot;, Trebuchet, sans-serif; font-size: 11pt;\\">\\n<br>\\n</div>\\n<div style=\\"text-align: left; text-indent: 0px; background-color: white; margin: 0px; font-family: &quot;Trebuchet MS&quot;, Trebuchet, sans-serif; font-size: 11pt;\\">\\n<br>\\n</div>\\n<div style=\\"text-align: left; text-indent: 0px; background-color: white; margin: 0px; font-family: &quot;Trebuchet MS&quot;, Trebuchet, sans-serif; font-size: 11pt;\\">\\n<span class=\\"spanWithBackgroundColor\\" style=\\"background-color: white;\\">Cordialement,</span></div>\\n<div style=\\"direction: ltr; text-indent: 0px; margin: 0px; font-family: &quot;Trebuchet MS&quot;, Trebuchet, sans-serif; font-size: 11pt; color: rgb(36, 36, 36);\\">\\n<br>\\n</div>\\n<div style=\\"direction: ltr; text-indent: 0px; margin: 0px; font-family: &quot;Trebuchet MS&quot;, Trebuchet, sans-serif; font-size: 11pt; color: rgb(36, 36, 36);\\">\\n<b>Ludivine SAUZADE</b></div>\\n<div style=\\"text-indent: 0px; margin: 0px; font-family: &quot;Trebuchet MS&quot;, Trebuchet, sans-serif; font-size: 11pt; color: rgb(36, 36, 36);\\">\\nAdjointe de Direction / CST Classes 2 à 9 / Responsable BU Services</div>\\n<div style=\\"text-indent: 0px; margin: 0px; font-family: &quot;Trebuchet MS&quot;, Trebuchet, sans-serif; font-size: 11pt;\\">\\n<b><br>\\n</b></div>\\n<div style=\\"text-indent: 0px; margin: 0px; font-family: &quot;Trebuchet MS&quot;, Trebuchet, sans-serif; font-size: 10pt;\\">\\n<b>UNITECH Services France SAS</b></div>\\n<div style=\\"text-indent: 0px; margin: 0px; font-family: &quot;Trebuchet MS&quot;, Trebuchet, sans-serif; font-size: 10pt;\\">\\n<b>Mob:</b>&nbsp;    +&nbsp; 33 7 69 13 71 47</div>\\n<div style=\\"text-indent: 0px; margin: 0px; font-family: &quot;Trebuchet MS&quot;, Trebuchet, sans-serif; font-size: 10pt;\\">\\n<b>Tél : </b>    &nbsp;+&nbsp; 33 4 75 00 63 04</div>\\n<div style=\\"text-align: left; text-indent: 0px; background-color: white; margin: 0px; font-family: &quot;Trebuchet MS&quot;, Trebuchet, sans-serif; font-size: 10pt;\\">\\n<span class=\\"spanWithBackgroundColor\\" style=\\"background-color: white;\\"><b>Adresse :</b>&nbsp; &nbsp;21B rue Antoine Becquerel - 26230 VALAURIE</span></div>\\n<div style=\\"text-align: left; text-indent: 0px; background-color: white; margin: 0px; font-family: &quot;Trebuchet MS&quot;, Trebuchet, sans-serif; font-size: 10pt; color: rgb(36, 36, 36);\\">\\n&lt;image.png&gt;</div>\\n<div style=\\"text-align: left; text-indent: 0px; background-color: wh