DER(0.33)[info@dfranklincreation.com,bounces+11623831-9883-comptabilite=ebanista.fr@send.eu.dfranklincreation.com];\\r\\n\\tR_SPF_ALLOW(-0.20)[+ip4:149.72.0.0/16];\\r\\n\\tR_DKIM_ALIGNED(-0.10)[relaxed];\\r\\n\\tR_DKIM_ALLOW(-0.10)[eu.dfranklincreation.com:s=kl2];\\r\\n\\tMIME_FROM_MX_GOOD(-0.10)[dfranklincreation-com.mail.protection.outlook.com];\\r\\n\\tMX_GOOD(-0.10)[mx.sendgrid.net];\\r\\n\\tMIME_GOOD(-0.10)[multipart/alternative,text/plain];\\r\\n\\tMANY_INVISIBLE_PARTS(0.06)[1];\\r\\n\\tHAS_LIST_UNSUB(-0.01)[];\\r\\n\\tRCVD_TLS_LAST(0.00)[];\\r\\n\\tTO_MATCH_ENVRCPT_ALL(0.00)[];\\r\\n\\tRCPT_COUNT_ONE(0.00)[1];\\r\\n\\tTO_DN_ALL(0.00)[];\\r\\n\\tDKIM_TRACE(0.00)[eu.dfranklincreation.com:+];\\r\\n\\tMIME_TRACE(0.00)[0:+,1:+,2:~];\\r\\n\\tRCVD_COUNT_TWO(0.00)[2];\\r\\n\\tFROM_NEQ_ENVFROM(0.00)[info@dfranklincreation.com,bounces@send.eu.dfranklincreation.com];\\r\\n\\tTAGGED_FROM(0.00)[11623831-9883-comptabilite=ebanista.fr];\\r\\n\\tALIAS_RESOLVED(0.00)[];\\r\\n\\tASN(0.00)[asn:11377, ipnet:149.72.64.0/19, country:US];\\r\\n\\tREDIRECTOR_URL(0.00)[klclick.com];\\r\\n\\tMISSING_XM_UA(0.00)[];\\r\\n\\tFROM_HAS_DN(0.00)[]",["215"],"<span class=\\"mp_address_group\\"><span class=\\"mp_address_name\\">Valentin Caufriez</span> &lt;<a href=\\"mailto:comptabilite@ebanista.fr\\" class=\\"mp_address_email\\">comptabilite@ebanista.fr</a>&gt;</span>","\\"Valentin Caufriez\\" <comptabilite@ebanista.fr>",["216"],"<span class=\\"mp_address_group\\"><span class=\\"mp_address_name\\">D.Franklin</span> &lt;<a href=\\"mailto:info@dfranklincreation.com\\" class=\\"mp_address_email\\">info@dfranklincreation.com</a>&gt;</span>","\\"D.Franklin\\" <info@dfranklincreation.com>",["217"],"System: Tu es un assistant qui trie les emails professionnels d'une entreprise de menuiserie/ébénisterie (EBANISTA). Pour chaque email, réponds UNIQUEMENT en JSON avec cette structure exacte :\\n{\\n  \\"categorie\\": \\"offre_fournisseur\\" | \\"confirmation_commande\\" | \\"prospects\\" | \\"suivi_client\\" | \\"administratif\\" | \\"litige\\" | \\"facturation\\" | \\"spam\\",\\n  \\"urgent\\": true ou false,\\n  \\"resume\\": \\"résumé en 2-3 lignes maximum\\",\\n  \\"auto_envoi_possible\\": true ou false,\\n  \\"reponse_requise\\": true ou false\\n}\\n\\nCatégories (avec exemples) :\\n- offre_fournisseur : devis, propositions commerciales ou catalogues reçus d'un fournisseur. Ex : \\"Devis panneaux MDF - validité 30 jours\\"\\n- confirmation_commande : accusés de réception ou confirmations d'une commande déjà passée à un fournisseur. Ex : \\"Confirmation de votre commande n°4521\\"\\n- prospects : demandes d'information ou de devis de particuliers/entreprises intéressés par nos services. Ex : \\"Devis pour cuisine sur mesure\\"\\n- suivi_client : échanges avec des clients déjà engagés sur un projet en cours. Ex : \\"Où en est mon meuble ?\\"\\n- administratif : courriers officiels, banque, assurance, impôts, RH. Ex : \\"Relevé bancaire disponible\\"\\n- litige : réclamation, mise en demeure, mention d'avocat/tribunal, forte insatisfaction client. TOUJOURS urgent=true et auto_envoi_possible=false.\\n- facturation : factures reçues ou envoyées, relances de paiement. Ex : \\"Facture n°2026-045\\"\\n- spam : newsletters, publicités, phishing évident, démarchage commercial non sollicité sans rapport avec l'activité.\\n\\nRègles d'urgence :\\n- Ne pas se fier au mot \\"urgent\\" dans le sujet s'il n'est pas justifié par le contenu réel (une simple question commerciale n'est pas urgente même si le sujet dit \\"urgent\\").\\n- Est urgent : litige (toujours), délai serré explicite (\\"réponse avant demain\\"), problème bloquant sur un chantier en cours, client insatisfait qui réclame.\\n\\nRègles auto_envoi_possible :\\n- true UNIQUEMENT pour : accusé de réception simple sans action requise, confirmation de rdv déjà validée, confirmation_commande (accusé fournisseur).\\n- false pour tout le reste, en particulier : offre_fournisseur, devis, facture, litige, toute demande nécessitant une réponse personnalisée ou une décision métier.\\n\\nRègles reponse_requise :\\n- true si l'expéditeur attend une vraie réponse rédigée de l'entreprise : question, demande de devis ou de prix, demande de rendez-vous ou de disponibilité, relance, réclamation, proposition à accepter ou refuser.\\n- false pour : spam, notifications et mails automatiques (y compris les réponses automatiques d'absence), accusés de réception et confirmations sans question, factures et relevés sans question, newsletters, mails reçus seulement en copie pour information.\\n\\nLe résumé doit être factuel et concis, sans reformuler tout l'email.\\nHuman: Voici un email à analyser :\\nExpéditeur : \\"D.Franklin\\" <info@dfranklincreation.com>\\nSujet : -15 % sur les chaussures | Pass VIP 🎫\\nContenu : https://www.dfranklincreation.com/\\nhttps://www.dfranklincreation.com/\\n[FEMME](https://www.dfranklincreation.com/pages/women)\\n[HOMME](https://www.dfranklincreation.com/pages/men)\\n[ATHLETIC](https://www.dfranklincreation.com/pages/athletic)\\n\\n[D.FRANKLIN](https://es.dfranklincreation.com/collections/shoes)\\n\\nNous avons activé ton VIP Pass, qui te donne droit à une réduction de 15 % sur les chaussures, aujourd’hui seulement.Viens compléter ton look grâce à cet avantage exclusif.\\n\\nCODE[VIP15](https://es.dfranklincreation.com/collections/shoes)\\n\\nCHOISISSEZ VOTRE POINTURE\\n\\n[FEMME](https://es.dfranklincreation.com/collections/women-shoes)\\n\\n[36](https://es.dfranklincreation.com/collections/women-shoes?filter.v.option.size=36&filter.v.availability=1)\\n\\n[37](https://es.dfranklincreation.com/collections/women-shoes?filter.v.option.size=37&filter.v.availability=1)\\n\\n[38](https://es.dfranklincreation.com/collections/women-shoes?filter.v.option.size=38&filter.v.availability=1)\\n\\n[39](https://es.dfranklincreation.com/collections/women-shoes?filter.v.option.size=39&filter.v.availability=1)\\n\\n[40](https://es.dfranklincreation.com/collections/women-shoes?filter.v.option.size=40&filter.v.availability=1)\\n\\n[41](https://es.dfranklincreation.com/collections/women-shoes?filter.v.option.size=41&filter.v.availability=1)\\n\\n[HOMME](https://es.dfranklincreation.com/collections/men-shoes)\\n\\n[41](https://es.dfranklincreation.com/collections/men-shoes?filter.v.option.size=41&filter.v.availability=1)\\n\\n[42](https://es.dfranklincreation.com/collections/men-shoes?filter.v.option.size=42&filter.v.availability=1)\\n\\n[43](https://es.dfranklincreation.com/collections/men-shoes?filter.v.option.size=43&filter.v.availability=1)\\n\\n[44](https://es.dfranklincreation.com/collections/men-shoes?filter.v.option.size=44&filter.v.availability=1)\\n\\n[45](https://es.dfranklincreation.com/collections/men-shoes?filter.v.option.size=45&filter.v.availability=1)\\n\\n[46](https://es.dfranklincreation.com/collections/men-shoes?filter.v.option.size=46&filter.v.availability=1)\\n\\nTélécharge notre appli\\n\\nhttps://apps.apple.com/app/d-franklin/id1559648503\\n\\nhttps://play.google.com/store/apps/details?id=co.tapcart.app.id_CamPLTQEI9&hl=es_NI&pli=1\\n\\n[D.Franklin](https://es.dfranklincreation.com/)\\n\\nSuis-nous  |  @DFRANKLINOFCL\\n\\nSi tu ne souhaites plus recevoir d'e-mails, tu peux [te désabonner](https://manage.kmail-lists.com/subscriptions/unsubscribe?a=KdhJQZ&c=01KXX797TXP61QDBT37NYX1CNQ&k=19adcbc08e8410380bc13a95773927ac&st=gAAAAABq6IIVYgWyyW4l3N2QQ1c7-8GSMGsi1oasA5lO-9303Iy0mLqSMqVW6NL694jzkefnhnisn40KFRqOoFxmoWhBl_WaYa1OXCrQpAc4destFnHs4d0%3D&m=01M6E1K2HQ5Z7D4MSV393N7D66&r=01M6E3Q2KGKYEAJJXJKJV0RCYH) ou [mettre à jour tes préférences](https://manage.kmail-lists.com/subscriptions/update?a=KdhJQZ&c=01KXX797TXP61QDBT37NYX1CNQ&k=19adcbc08e8410380bc13a95773927ac&st=gAAAAABq6IIVYgWyyW4l3N2QQ1c7-8GSMGsi1oasA5lO-9303Iy0mLqSMqVW6NL694jzkefnhnisn40KFRqOoFxmoWhBl_WaYa1OXCrQpAc4destFnHs4d0%3D&m=01M6E1K2HQ5Z7D4MSV393N7D66&r=01M6E3Q2KGKYEAJJXJKJV0RCYH).\\nConsulte notre [Politique de confidentialité](https://es.dfranklincreation.com/pages/privacy-policy) et notre [Politique relative aux cookies](https://es.dfranklincreation.com/pages/cookies-policy).\\nPour toute question, consulte notre [section de contact](https://es.dfranklincreation.com/pages/contact).\\n\\nD.Franklin EU C/ Xixona, 3 Elche, Alicante 03204\\n",{"lc":1,"type":"218","id":"219"},"claude-sonnet-4-6","https://api.anthropic.com",{},{"fetchOptions":"220"},{"lc":1,"type":"218","id":"221"},{"address":"222","name":"223"},{"address":"224","name":"225"},["226"],"secret",["227"],{},["227"],"comptabilite@ebanista.fr","Valentin Caufriez","info@dfranklincreation.com","D.Franklin",{"text":"159"},"ANTHROPIC_API_KEY"]	b24ff535-dba4-49f6-a639-0e6a29640469
786	{"id":"lfynCIkeDPS6hIXu","name":"Digest quotidien 7h - v.caufriez","nodes":[{"parameters":{"notice":"","rule":{"interval":[{"field":"cronExpression","notice":"","expression":"0 7 * * *"}]},"skipDurableScheduler":false},"type":"n8n-nodes-base.scheduleTrigger","typeVersion":1.2,"position":[0,0],"id":"d1a1b111-0000-4000-8000-000000000001","name":"Schedule Trigger 7h"},{"parameters":{"curlImport":"","method":"GET","url":"http://localhost:5678/api/v1/data-tables/IgT0r6Yg3ZtzMWNR/rows","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","provideSslCertificates":false,"sendQuery":true,"specifyQuery":"keypair","queryParameters":{"parameters":[{"name":"limit","value":"250"}]},"sendHeaders":false,"sendBody":false,"options":{},"infoMessage":""},"type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[224,0],"id":"d1a1b111-0000-4000-8000-000000000002","name":"Get digest_mails rows","credentials":{"httpHeaderAuth":{"id":"Lfuh7XFXewkeDjJe","name":"n8n API Key (interne)"}}},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"const rows = $input.first().json.data || [];\\n\\nconst LIMIT = 3800; // limite Telegram : 4096 caractères par message\\nconst LABELS = { 'v.caufriez': 'v.caufriez@ebanista.fr', 'contact': 'contact@ebanista.fr', 'comptabilite': 'comptabilite@ebanista.fr' };\\nconst ORDER = ['v.caufriez', 'contact', 'comptabilite'];\\n\\nif (rows.length === 0) {\\n  return [{ json: { text: \\"📋 Digest quotidien EBANISTA\\\\n\\\\nAucun mail à traiter aujourd'hui.\\", count: 0 } }];\\n}\\n\\n// regroupement par boîte (les anciennes lignes sans boîte viennent de v.caufriez)\\nconst groups = {};\\nfor (const r of rows) {\\n  const box = r.boite || 'v.caufriez';\\n  (groups[box] = groups[box] || []).push(r);\\n}\\nconst boxes = [...ORDER.filter(b => groups[b]), ...Object.keys(groups).filter(b => !ORDER.includes(b))];\\n\\n// un bloc de texte par boîte, puis découpage en messages de taille raisonnable\\nconst blocks = [];\\nfor (const box of boxes) {\\n  const list = groups[box];\\n  blocks.push(`📥 ${LABELS[box] || box} (${list.length})`);\\n  for (const r of list) {\\n    blocks.push(`• [${r.categorie}] ${r.expediteur}\\\\n  ${r.resume}`);\\n  }\\n}\\n\\nconst header = `📋 Digest quotidien EBANISTA — ${rows.length} mail(s)`;\\nconst chunks = [];\\nlet current = header;\\nfor (const b of blocks) {\\n  const next = current + '\\\\n\\\\n' + b;\\n  if (next.length > LIMIT && current !== header) {\\n    chunks.push(current);\\n    current = '(suite)\\\\n\\\\n' + b;\\n  } else {\\n    current = next;\\n  }\\n}\\nchunks.push(current);\\n\\nreturn chunks.map(text => ({ json: { text, count: rows.length } }));\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[448,0],"id":"d1a1b111-0000-4000-8000-000000000003","name":"Build digest text"},{"parameters":{"resource":"message","operation":"sendMessage","chatId":"8848139246","text":"={{ (($json.text)).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') }}","replyMarkup":"none","additionalFields":{"appendAttribution":false,"parse_mode":"HTML"}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[672,0],"id":"d1a1b111-0000-4000-8000-000000000004","name":"Send digest to Telegram","credentials":{"telegramApi":{"id":"duvmoy6UkxnbnBdr","name":"Ebanista Mails"}},"webhookId":"363c01d7-51fe-4fad-9eaa-5b88407a022d"},{"parameters":{"curlImport":"","method":"DELETE","url":"http://localhost:5678/api/v1/data-tables/IgT0r6Yg3ZtzMWNR/rows/clear","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","provideSslCertificates":false,"sendQuery":false,"sendHeaders":false,"sendBody":false,"options":{},"infoMessage":""},"type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[896,0],"id":"d1a1b111-0000-4000-8000-000000000005","name":"Clear digest_mails table","credentials":{"httpHeaderAuth":{"id":"Lfuh7XFXewkeDjJe","name":"n8n API Key (interne)"}}}],"connections":{"Schedule Trigger 7h":{"main