-4000-8000-00000000f001","leftValue":"={{ $json.categorie }}","rightValue":"spam","operator":{"type":"string","operation":"notEquals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.filter","typeVersion":2.2,"position":[1344,0],"id":"f1a1b111-0000-4000-8000-000000000010","name":"Filtrer spam"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"f1a1b111-0000-4000-8000-00000000f002","leftValue":"={{ $json.auto_envoi_possible }}","rightValue":"","operator":{"type":"boolean","operation":"true","singleValue":true}},{"id":"f1a1b111-0000-4000-8000-00000000f004","leftValue":"={{ $('Email Trigger (IMAP)').item.json.from.text }}","rightValue":"/(no[-_. ]?reply|ne[-_. ]?pas[-_. ]?r[eé]pondre|do[-_. ]?not[-_. ]?reply|mailer-daemon|postmaster|bounces?@)/i","operator":{"type":"string","operation":"notRegex"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1568,432],"id":"f1a1b111-0000-4000-8000-000000000011","name":"Auto-envoi possible ?"},{"parameters":{"resource":"email","operation":"send","fromEmail":"v.caufriez@ebanista.fr","toEmail":"={{ $('Email Trigger (IMAP)').item.json.from.text }}","subject":"=Re: {{ $('Email Trigger (IMAP)').item.json.subject }}","emailFormat":"text","text":"={{ $json.text }}","options":{"appendAttribution":false}},"type":"n8n-nodes-base.emailSend","typeVersion":2.1,"position":[2016,432],"id":"f1a1b111-0000-4000-8000-000000000012","name":"Envoyer accusé de réception","credentials":{"smtp":{"id":"HpY9yQWKI4eEr1b8","name":"SMTP - v.caufriez@ebanista.fr"}},"webhookId":"6f85610d-11ce-4c46-a2c5-3fa634b90499"},{"parameters":{"notice":"","promptType":"define","text":"=Voici l'email reçu à confirmer :\\nExpéditeur : {{ $('Email Trigger (IMAP)').item.json.from.text }}\\nSujet : {{ $('Email Trigger (IMAP)').item.json.subject }}\\nContenu : {{ $('Email Trigger (IMAP)').item.json.text }}\\n\\nRédige un accusé de réception personnalisé pour cet email.","hasOutputParser":false,"needsFallback":false,"messages":{"messageValues":[{"type":"SystemMessagePromptTemplate","message":"Tu rédiges des accusés de réception courts et personnalisés au nom d'EBANISTA (entreprise de menuiserie/ébénisterie), en réponse à un email reçu.\\n\\nRéponds UNIQUEMENT avec le corps du texte de l'email de réponse : pas de JSON, pas de sujet, pas de formule d'introduction du type \\"Voici votre réponse\\", juste le message tel qu'il sera envoyé.\\n\\nConsignes :\\n- 3 à 5 lignes maximum, en français, ton chaleureux et professionnel\\n- Fais référence brièvement à l'objet de sa demande pour montrer que le message a été lu\\n- Ne promets aucun délai précis ni aucune information que tu ne connais pas\\n- Termine par une formule de politesse et la signature \\"L'équipe EBANISTA\\""}]},"batching":{}},"type":"@n8n/n8n-nodes-langchain.chainLlm","typeVersion":1.9,"position":[1792,336],"id":"f1a1b111-0000-4000-8000-000000000013","name":"Rédiger accusé personnalisé"},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"const folderMap = {\\n  offre_fournisseur: 'Tri-Offre fournisseur',\\n  confirmation_commande: 'Tri-Confirmation de commande',\\n  prospects: 'Tri-Prospects',\\n  suivi_client: 'Tri-SuiviClient',\\n  administratif: 'Tri-Administratif',\\n  litige: 'Tri-Litige',\\n  facturation: 'Tri-Facturation',\\n  spam: 'Spam'\\n};\\n\\n// Traite TOUS les mails d'un lot (plusieurs mails peuvent arriver en même temps)\\nreturn $input.all().map((entry, i) => {\\n  const item = entry.json;\\n  const targetFolder = folderMap[item.categorie] || 'Tri-Administratif';\\n  // Marqué comme lu uniquement si aucune action de votre part n'est nécessaire : réponse automatisée, ou spam.\\n  const markAsRead = item.auto_envoi_possible === true || item.categorie === 'spam';\\n  return { json: { ...item, targetFolder, markAsRead }, pairedItem: { item: i } };\\n});