lHq7DZDS69rykpUBQmsCN72fxmxaQq2XHhEXBjbvvIu3nKQgpmHI8tuxJaP22vVKqbXbd1fC4pX2Qq7Yf7u38NXI5cp0hSIzCzripCBVaZOFK4dLd4GL68tts3e51nlvxnRacubQSml1U5A7ry24Nut2a6JYs","X-Rspamd-Server: rspamd-768db7748c-mtrzg","X-Rspamd-Queue-Id: 4jFf704gwyzYSB","X-Spamd-Result: default: False [-1.10 / 40.00];\\r\\n\\tDMARC_POLICY_ALLOW(-0.50)[pouey.com,quarantine];\\r\\n\\tR_SPF_ALLOW(-0.20)[+a:dispatch-eu.ppe-hosted.com];\\r\\n\\tMX_GOOD(-0.10)[mx1-eu1.ppe-hosted.com];\\r\\n\\tR_DKIM_ALLOW(-0.10)[pouey.com:s=ppe-04-2022,Pouey1.onmicrosoft.com:s=selector1-Pouey1-onmicrosoft-com];\\r\\n\\tR_DKIM_ALIGNED(-0.10)[strict];\\r\\n\\tMIME_GOOD(-0.10)[multipart/related,multipart/alternative,text/plain];\\r\\n\\tMISSING_XM_UA(0.00)[];\\r\\n\\tASN(0.00)[asn:52129, ipnet:185.132.181.0/24, country:US];\\r\\n\\tMIME_TRACE(0.00)[0:+,1:+,2:+,3:~,4:~,5:~,6:~];\\r\\n\\tRCPT_COUNT_ONE(0.00)[1];\\r\\n\\tRCVD_COUNT_THREE(0.00)[3];\\r\\n\\tPREVIOUSLY_DELIVERED(0.00)[contact@ebanista.fr];\\r\\n\\tFROM_HAS_DN(0.00)[];\\r\\n\\tRCVD_TLS_LAST(0.00)[];\\r\\n\\tFROM_EQ_ENVFROM(0.00)[];\\r\\n\\tTO_MATCH_ENVRCPT_ALL(0.00)[];\\r\\n\\tTO_DN_EQ_ADDR_ALL(0.00)[];\\r\\n\\tDKIM_TRACE(0.00)[pouey.com:+,Pouey1.onmicrosoft.com:+]","X-Rspamd-Action: no action",["328"],"<span class=\\"mp_address_group\\"><a href=\\"mailto:contact@ebanista.fr\\" class=\\"mp_address_email\\">contact@ebanista.fr</a></span>","contact@ebanista.fr",["329"],"<span class=\\"mp_address_group\\"><span class=\\"mp_address_name\\">CHAPEYROU Marie</span> &lt;<a href=\\"mailto:marie.chapeyrou@pouey.com\\" class=\\"mp_address_email\\">marie.chapeyrou@pouey.com</a>&gt;</span>","image/png","image","png","filesystem-v2","image001.png","filesystem-v2:workflows/yBUJ2dGEjAusKSuD/executions/temp/binary_data/0a799a33-854f-4721-ab49-062f65c0d874","5.29 kB","image002.png","filesystem-v2:workflows/yBUJ2dGEjAusKSuD/executions/temp/binary_data/6fc4ec98-b3e9-49a1-b18a-b65d214b00c5","3.69 kB","image003.png","filesystem-v2:workflows/yBUJ2dGEjAusKSuD/executions/temp/binary_data/f5ce9bf5-880d-4606-9ef1-721aa25e307f","47.9 kB",["330"],"System: Tu es un assistant qui trie les emails professionnels d'une entreprise de menuiserie/ébénisterie (EBANISTA). Pour chaque email, réponds UNIQUEMENT en JSON avec cette structure exacte :\\n{\\n  \\"categorie\\": \\"offre_fournisseur\\" | \\"confirmation_commande\\" | \\"prospects\\" | \\"suivi_client\\" | \\"administratif\\" | \\"litige\\" | \\"facturation\\" | \\"spam\\",\\n  \\"urgent\\": true ou false,\\n  \\"resume\\": \\"résumé en 2-3 lignes maximum\\",\\n  \\"auto_envoi_possible\\": true ou false,\\n  \\"reponse_requise\\": true ou false\\n}\\n\\nCatégories (avec exemples) :\\n- offre_fournisseur : devis, propositions commerciales ou catalogues reçus d'un fournisseur. Ex : \\"Devis panneaux MDF - validité 30 jours\\"\\n- confirmation_commande : accusés de réception ou confirmations d'une commande déjà passée à un fournisseur. Ex : \\"Confirmation de votre commande n°4521\\"\\n- prospects : demandes d'information ou de devis de particuliers/entreprises intéressés par nos services. Ex : \\"Devis pour cuisine sur mesure\\"\\n- suivi_client : échanges avec des clients déjà engagés sur un projet en cours. Ex : \\"Où en est mon meuble ?\\"\\n- administratif : courriers officiels, banque, assurance, impôts, RH. Ex : \\"Relevé bancaire disponible\\"\\n- litige : réclamation, mise en demeure, mention d'avocat/tribunal, forte insatisfaction client. TOUJOURS urgent=true et auto_envoi_possible=false.\\n- facturation : factures reçues ou envoyées, relances de paiement. Ex : \\"Facture n°2026-045\\"\\n- spam : newsletters, publicités, phishing évident, démarchage commercial non sollicité sans rapport avec l'activité.\\n\\nRègles d'urgence :\\n- Ne pas se fier au mot \\"urgent\\" dans le sujet s'il n'est pas justifié par le contenu réel (une simple question commerciale n'est pas urgente même si le sujet dit \\"urgent\\").\\n- Est urgent : litige (toujours), délai serré explicite (\\"réponse avant demain\\"), problème bloquant sur un chantier en cours, client insatisfait qui réclame.\\n\\nRègles auto_envoi_possible :\\n- true UNIQUEMENT pour : accusé de réception simple sans action requise, confirmation de rdv déjà validée, confirmation_commande (accusé fournisseur).\\n- false pour tout le reste, en particulier : offre_fournisseur, devis, facture, litige, toute demande nécessitant une réponse personnalisée ou une décision métier.\\n\\nRègles reponse_requise :\\n- true si l'expéditeur attend une vraie réponse rédigée de l'entreprise : question, demande de devis ou de prix, demande de rendez-vous ou de disponibilité, relance, réclamation, proposition à accepter ou refuser.\\n- false pour : spam, notifications et mails automatiques (y compris les réponses automatiques d'absence), accusés de réception et confirmations sans question, factures et relevés sans question, newsletters, mails reçus seulement en copie pour information.\\n\\nLe résumé doit être factuel et concis, sans reformuler tout l'email.\\nHuman: Voici un email à analyser :\\nExpéditeur : \\"CHAPEYROU Marie\\" <marie.chapeyrou@pouey.com>\\nSujet : Comptes 2026 - POUEY International - Garanties fournisseurs\\nContenu : [cid:image001.png@01DD6790.41BDC410]\\n\\n\\n898740279 - EBANISTA\\nSERVICE GARANTIES FOURNISSEURS POUEY INTERNATIONAL\\nMonsieur,\\nComme évoqué lors de notre entretien téléphonique du 29/10/2026, nous procédons actuellement à l'évaluation des lignes de garanties pouvant être accordées à EBANISTA.\\n\\nPourriez-vous nous transmettre les comptes sociaux 03/2026, ceux-ci n'étant à ce jour pas déposés au greffe ni en Banque de France.\\nAussi, pourriez-vous nous communiquer le prévisionnel (chiffre d'affaires et résultats) pour l'exercice en cours (03/2027).\\n\\nNous vous remercions par avance de votre collaboration et restons à votre disposition pour tout complément d'information.\\nBien cordialement,\\n\\n\\n\\n[cid:image002.png@01DD6790.41BDC410]\\nMarie CHAPEYROU\\nGestionnaire Crédit\\nTel : +33 5 56 56 48 12\\nMail : marie.chapeyrou @pouey.com<mailto:mariesol.lopez@pouey.com>\\nwww.pouey.com<http://www.pouey.com/>\\n[cid:image003.png@01DD6790.41BDC410]\\n\\nPOUEY RENSEIGNEMENT COMMERCIAL GARANTI (P.R.C.G.) Siren 414.494.419, est agréée par l'ACPR (Autorité de Contrôle Prudentiel et de Résolution - institution intégrée à la Banque de France) sous le matricule n°4021213.\\nDans le cadre de notre activité nous sommes amenés à coter les Entreprises afin d'accorder des garanties financières pour la couverture des risques de crédit.\\nL'article L.511-33 du Code Monétaire et Financier dispose que les informations peuvent être communiquées aux agences de notation pour les besoins de la notation des produits financiers et, d'autre part, aux personnes avec lesquelles elles sont nécessaires pour la négociation, la conclusion ou l'exécution de certaines opérations telles que les opérations de crédit effectuées, directement ou indirectement, par un ou plusieurs établissements de crédit ou sociétés de financement, garanties ou d'assurance destinées à la couverture d'un risque de crédit.\\nDans le cadre de l'application de l'article L511-33 du CMF, notre démarche est officielle et légitime\\n\\nCe message, ainsi que les pièces jointes, sont établis, sous la seule responsabilité de l'expéditeur, à l'intention exclusive de ses destinataires ; ils peuvent contenir des informations confidentielles. Toute publication, utilisation ou diffusion doit être autorisée préalablement. L'intégrité de ce message n'étant pas assurée sur internet, POUEY International ne peut être tenu responsable de son contenu. Si vous n'êtes pas destinataire de ce message, merci de le détruire et d'avertir l'expéditeur.Conformément au Règlement RGPD 2016/679, vous bénéficiez d'un droit d'accès, de rectification, d'opposition et de portabilité des informations qui vous concernent. Vous pouvez exercer ce droit en vous adressant au Responsable Conformité par mail conformite@pouey.com ou par courrier POUEY INTERNATIONAL, CS 30535, 33002 BORDEAUX.\\n\\n",{"lc":1,"type":"331","id":"332"},"claude-sonnet-4-6","https://api.anthropic.com",{},{"fetchOptions":"333"},{"lc":1,"type":"331","id":"334"},"dAXiYGhwrnLjIbHU","707",{"address":"302","name":"335"},{"address":"225","name":"226"},["336"],"secret",["337"],{},["337"],"",{"text":"222"},"ANTHROPIC_API_KEY"]	9ae720d1-6695-40df-bb06-2ffc14b6dde8
707	{"id":"dAXiYGhwrnLjIbHU","name":"Brouillon de réponse - contact","nodes":[{"parameters":{"events":"worklfow_call","inputSource":"passthrough","returnOutput":"lastRunOnly"},"type":"n8n-nodes-base.executeWorkflowTrigger","typeVersion":1.1,"position":[0,0],"id":"a1000000-0000-4000-8000-000000000001","name":"Entrée sous-workflow"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"getEmailsList","mailboxPath":{"__rl":true,"mode":"path","value":"Sent"},"emailDateRange":{"since":"={{ $now.minus({ years: 1 }).toISO() }}"},"emailFlags":{},"emailSearchFilters":{"to":"={{ $json.from_address || 'adresse-introuvable@invalid.invalid' }}"},"limit":40,"includeParts":["textContent"]},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[260,0],"id":"a1000000-0000-4000-8000-000000000002","name":"Retrouver mes réponses précédentes","alwaysOutputData":true,"onError":"continueRegularOutput","credentials":{"imap":{"id":"nFnyy1qJ60BZTKsw","name":"IMAP - contact@ebanista.fr"}}},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Assemble le prompt : mail reçu + historique des réponses précédentes à ce correspondant\\nconst src = $('Entrée sous-workflow').first().json;\\nconst found = $input.all().map(i => i.json).filter(j => j && j.envelope && !j.error);\\n\\nconst ownText = (t) => String(t || '').replace(/\\\\r/g, '')\\n  .split(/\\\\n(?:>|Le .{5,90} a écrit|De ?:|From:|-----Original|On .{5,90} wrote)/)[0].trim();\\n\\nconst history = found\\n  .map(j => ({ date: new Date(j.envelope.date || 0), subject: j.envelope.subject || '', text: ownText(j.textContent) }))\\n  .filter(h => h.text.length >= 30)\\n  .sort((a, b) => b.date - a.date)\\n  .slice(0, 3)\\n  .map((h, n) => `--- Échange ${n + 1} (${h.date.toISOString().slice(0, 10)}, objet : ${h.subject}) ---\\\\n${h.text.slice(0, 700)}`)\\n  .join('\\\\n\\\\n');\\n\\nconst body = String(src.text || '').trim().slice(0, 4000);\\nconst prompt = [\\n  'MAIL REÇU',\\n  `De : ${src.from_name ? src.from_name + ' ' : ''}<${src.from_address}>`,\\n  `Objet : ${src.subject}`,\\n  `Date : ${src.date}`,\\n  `Résumé (assistant de tri) : ${src.resume || ''}`,\\n  '',\\n  'Contenu :',\\n  body || '(message sans texte)',\\n  '',\\n  'HISTORIQUE : tes dernières réponses à cet interlocuteur (de la plus récente à la plus ancienne)',\\n  history || \\"(aucun échange précédent trouvé : vouvoie par défaut)\\",\\n  '',\\n  'Rédige le brouillon de réponse.'\\n].join('\\\\n');\\n\\nreturn [{ json: { prompt, historyCount: history ? history.split('--- Échange ').length - 1 : 0 } }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[520,0],"id":"a1000000-0000-4000-8000-000000000003","name":"Assembler le contexte"},{"parameters":{"notice":"","promptType":"define","text":"={{ $json.prompt }}","hasOutputParser":false,"needsFallback":false,"messages":{"messageValues":[{"type":"SystemMessagePromptTemplate","message":"Tu rédiges des BROUILLONS de réponses d'e-mails pour la boîte administrative d'EBANISTA (menuiserie / ébénisterie sur mesure). Cette boîte sert au secrétariat, à la comptabilité, aux ressources humaines et aux échanges avec les clients et les fournisseurs. La personne qui la gère relira et modifiera chaque brouillon avant de l'envoyer : tu écris à sa place, dans son style.\\n\\nRéponds UNIQUEMENT avec le corps du message : pas d'objet, pas de commentaire, pas de guillemets, pas de balises.\\n\\nSTYLE (tiré des mails envoyés depuis cette boîte) :\\n- Vouvoiement quasi systématique, ton poli, professionnel et courtois, sans familiarité. Tutoie uniquement si l'historique de ses échanges avec cette personne montre qu'elle la tutoie.\\n- Salutation : \\"Bonjour,\\" ou \\"Bonjour Prénom,\\" ; \\"Bonjour Madame Nom,\\" / \\"Bonjour Monsieur Nom,\\" avec un interlocuteur formel. Mets un prénom ou un nom seulement si tu en es sûr.\\n- Phrases complètes et claires, paragraphes courts (3 à 8 lignes en général). Formules typiques : \\"Je reviens vers vous concernant …\\", \\"Merci pour votre retour.\\", \\"Merci beaucoup pour l'envoi de …\\", \\"Vous trouverez en pièce jointe …\\", \\"Je vous mets … en pièce jointe.\\".\\n- Demandes précises : \\"Pourriez-vous …\\", \\"Serait-il possible de …\\". Si plusieurs points, une liste à puces.\\n- Avant la fin : \\"Merci d'avance pour votre retour.\\" ou \\"Je vous remercie par avance pour votre retour.\\"\\n- Formule de fin : \\"Cordialement,\\" ou \\"Bien cordialement,\\", parfois \\"Bonne journée,\\" / \\"Belle journée,\\".\\n- Signature : écris exactement [À COMPLÉTER : signature] sur la dernière ligne, sous la formule de fin.\\n- Réclamation, litige ou retard (facture erronée, résiliation, livraison manquante) : ton ferme, calme et factuel ; rappelle les dates, références et faits qui figurent dans le mail reçu ; demande clairement ce qui est attendu et dans quel délai si le mail le permet.\\n\\nRÈGLES STRICTES :\\n- N'invente JAMAIS un montant, un nombre d'heures, une date, un délai, un numéro de contrat ou de dossier, une référence, une quantité ni un engagement. Si une information nécessaire manque, écris [À COMPLÉTER : ce qu'il faut préciser] à l'endroit voulu.\\n- Les DÉCISIONS ne sont jamais à ta charge : accepter ou refuser une offre, valider un devis, passer ou annuler une commande, payer, fixer une date, accorder un geste commercial, valider une demande d'un salarié. N'écris jamais \\"oui\\", \\"c'est d'accord\\", \\"je confirme\\" ou \\"nous validons\\" à sa place. Écris [À COMPLÉTER : décision à prendre (ce qu'il faut trancher)] ou une réponse neutre (accuser réception, demander une précision, dire que tu reviens vers l'interlocuteur).\\n- N'ajoute AUCUNE précision (références, dimensions, quantités, noms de personnes, détails de paie ou de contrat) qui n'est pas dans le mail reçu, même si elle apparaît dans l'historique : l'historique ne sert qu'à choisir le ton (tu / vous), la salutation et la formule de fin. Ne reprends jamais d'informations personnelles d'un ancien échange.\\n- Sujets sensibles (paie, ressources humaines, rupture de contrat, litiges juridiques) : reste neutre et prudent, n'engage pas l'entreprise, laisse [À COMPLÉTER] pour toute information ou décision.\\n- Réponds à toutes les questions posées dans le mail reçu, point par point si nécessaire.\\n- Écris en français, sauf si l'interlocuteur écrit dans une autre langue : réponds alors dans sa langue.\\n- Ne cite pas l'historique et ne recopie pas le mail reçu."}]},"batching":{}},"type":"@n8n/n8n-nodes-langchain.chainLlm","typeVersion":1.9,"position":[780,0],"id":"a1000000-0000-4000-8000-000000000004","name":"Rédiger le brouillon"},{"parameters":{"notice":"","model":{"__rl":true,"mode":"list","value":"claude-sonnet-4-6","cachedResultName":"Claude Sonnet 4.6"},"options":{"temperature":0.4}},"type":"@n8n/n8n-nodes-langchain.lmChatAnthropic","typeVersion":1.5,"position":[820,220],"id":"a1000000-0000-4000-8000-000000000005","name":"Modèle Claude (brouillon)","credentials":{"anthropicApi":{"id":"FRxZizEr7zCaHHZp","name":"Claude API"}}},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Compose un e-mail RFC822 (réponse) à enregistrer dans le dossier Brouillons\\nconst src = $('Entrée sous-workflow').first().json;\\nconst draft = String($input.first().json.text || '').trim();\\nif (!draft) throw new Error('Brouillon vide renvoyé par le modèle');\\n\\nconst MY = { name: 'Ebanista', addr: 'contact@ebanista.fr' };\\nconst CRLF = '\\\\r\\\\n';\\nconst b64 = (s) => Buffer.from(s, 'utf8').toString('base64');\\nconst isAscii = (s) => /^[\\\\x20-\\\\x7e]*$/.test(s);\\n\\n// en-tête non ASCII -> mots encodés (RFC 2047), découpés en petits morceaux\\nconst encodeHeader = (s) => {\\n  if (isAscii(s)) return s;\\n  const chars = Array.from(s), parts = [];\\n  for (let i = 0; i < chars.length; i += 10) parts.push(`=?UTF-8?B?${b64(chars.slice(i, i + 10).join(''))}?=`);\\n  return parts.join(CRLF + ' ');\\n};\\nconst displayName = (name) => {\\n  if (!name) return '';\\n  // nom non ASCII : un seul mot encodé (le découper en plusieurs mots encodés le coupe à l'affichage)\\n  if (!isAscii(name)) return `=?UTF-8?B?${b64(name)}?=`;\\n  return /[^\\\\w .'-]/.test(name) ? `\\"${name.replace(/([\\"\\\\\\\\])/g, '\\\\\\\\$1')}\\"` : name;\\n};\\n\\nlet subject = String(src.subject || '').trim();\\nwhile (/^(re|ré)\\\\s*:\\\\s*/i.test(subject)) subject = subject.replace(/^(re|ré)\\\\s*:\\\\s*/i, '');\\nsubject = 'Re: ' + subject;\\n\\nconst origId = src.message_id ? (String(src.message_id).startsWith('<') ? src.message_id : `<${src.message_id}>`) : '';\\nconst when = src.date ? new Date(src.date).toLocaleString('fr-FR', { timeZone: 'Europe/Paris', dateStyle: 'long', timeStyle: 'short' }) : '';\\nconst who = (src.from_name ? src.from_name + ' ' : '') + `<${src.from_address}>`;\\nconst quoted = String(src.text || '').replace(/\\\\r/g, '').trim().slice(0, 3000).split('\\\\n').map(l => '> ' + l).join('\\\\n');\\nconst text = `${draft}\\\\n\\\\n\\\\nLe ${when}, ${who} a écrit :\\\\n${quoted}\\\\n`;\\n\\nconst headers = [\\n  `From: ${displayName(MY.name)} <${MY.addr}>`,\\n  `To: ${src.from_name ? displayName(src.from_name) + ' ' : ''}<${src.from_address}>`,\\n  `Subject: ${encodeHeader(subject)}`,\\n  `Date: ${new Date().toUTCString().replace('GMT', '+0000')}`,\\n  `Message-ID: <draft-${Date.now()}-${Math.random().toString(36).slice(2, 10)}@ebanista.fr>`,\\n  ...(origId ? [`In-Reply-To: ${origId}`, `References: ${origId}`] : []),\\n  'MIME-Version: 1.0',\\n  'Content-Type: text/plain; charset=UTF-8',\\n  'Content-Transfer-Encoding: base64',\\n];\\nconst bodyB64 = b64(text.replace(/\\\\n/g, CRLF)).replace(/(.{76})/g, '$1' + CRLF);\\n\\nreturn [{ json: { rfc822: headers.join(CRLF) + CRLF + CRLF + bodyB64 + CRLF, subject, draftPreview: draft } }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1100,0],"id":"a1000000-0000-4000-8000-000000000006","name":"Composer le brouillon"},{"param