tes.uid }}"}}]}}]},"additionalFields":{"appendAttribution":false,"parse_mode":"HTML"}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[1568,48],"id":"a00d2675-2c89-4e0f-b077-76de969ad947","name":"Send a text message","webhookId":"98c72095-6cdf-4118-b2eb-fece056cf3aa","credentials":{"telegramApi":{"id":"duvmoy6UkxnbnBdr","name":"Ebanista Mails"}}},{"parameters":{"resource":"row","operation":"insert","dataTableId":{"__rl":true,"value":"IgT0r6Yg3ZtzMWNR","mode":"list","cachedResultName":"digest_mails","cachedResultUrl":"/projects/WBZOJkoq8ImSC8dI/datatables/IgT0r6Yg3ZtzMWNR"},"columns":{"mappingMode":"defineBelow","value":{"auto_envoye":"={{ $json.auto_envoi_possible }}","expediteur":"={{ $('Email Trigger (IMAP)').item.json.from.text }}","categorie":"={{ $json.categorie }}","resume":"={{ $json.resume }}","date":"={{ $now.format('yyyy-MM-dd HH:mm') }}"},"matchingColumns":[],"schema":[{"id":"date","displayName":"date","required":false,"defaultMatch":false,"display":true,"type":"dateTime","readOnly":false,"removed":false},{"id":"expediteur","displayName":"expediteur","required":false,"defaultMatch":false,"display":true,"type":"string","readOnly":false,"removed":false},{"id":"categorie","displayName":"categorie","required":false,"defaultMatch":false,"display":true,"type":"string","readOnly":false,"removed":false},{"id":"resume","displayName":"resume","required":false,"defaultMatch":false,"display":true,"type":"string","readOnly":false,"removed":false},{"id":"auto_envoye","displayName":"auto_envoye","required":false,"defaultMatch":false,"display":true,"type":"boolean","readOnly":false,"removed":false}],"attemptToConvertTypes":false,"convertFieldsToString":false},"options":{}},"type":"n8n-nodes-base.dataTable","typeVersion":1.1,"position":[1568,240],"id":"122b45a3-88b0-46be-be02-8b79a661cf3f","name":"Insert row"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"f1a1b111-0000