false,"boite":"204","id":439,"createdAt":"205","updatedAt":"205"},{"item":0},{"boite":"204","recu_le":"184","from_address":"206","from_name":"207","subject":"183","message_id":"187","extrait":"208","resume":"201","categorie":"200","uid":"209","id":209,"createdAt":"210","updatedAt":"210"},{"item":0},{"categorie":"200","urgent":false,"resume":"201","auto_envoi_possible":false,"reponse_requise":false,"targetFolder":"211","markAsRead":false},{"item":0},{"item":0},{"path":"212","destination":"211","uidValidity":"213","uidMap":"214"},{"item":0},{"return-path":"215","delivered-to":"216","received":"217","authentication-results":"218","dkim-signature":"219","dkim-filter":"220","content-transfer-encoding":"221","content-type":"222","mime-version":"223","date":"224","to":"225","subject":"226","from":"227","x-mailer":"228","message-id":"229","x-spam-score":"230","x-spam-detail":"231","x-spam-verdict":"232","x-spam-state":"233","x-infomaniak-type":"234","x-infomaniak-spam":"235","x-infomaniak-cause":"236","x-rspamd-queue-id":"237","x-spamd-result":"238","x-rspamd-action":"239","x-rspamd-server":"240"},"<!doctype html><html xmlns=\\"http://www.w3.org/1999/xhtml\\" xmlns:v=\\"urn:schemas-microsoft-com:vml\\" xmlns:o=\\"urn:schemas-microsoft-com:office:office\\"><head><title></title><meta http-equiv=\\"X-UA-Compatible\\" content=\\"IE=edge\\"><meta http-equiv=\\"Content-Type\\" content=\\"text/html; charset=UTF-8\\"><meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1\\"><style type=\\"text/css\\">a{color:#A63950;}#outlook a{padding:0}.ReadMsgBody{width:100%}.ExternalClass{width:100%}.ExternalClass *{line-height:100%}body{margin:0;padding:0;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%}table,td{border-collapse:collapse;mso-table-lspace:0pt;mso-table-rspace:0pt}img{border:0;height:auto;line-height:100%;outline:none;text-decoration:none;-ms-interpolation-mode:bicubic}p{display:block;margin:13px 0}</style><style type=\\"text/css\\">@media only screen and (max-width:480px){@-ms-viewport{width:320px}@viewport{width:320px}}</style><style type=\\"text/css\\">@media only screen and (min-width:480px){.mj-column-per-100{width:100% !important}.mj-column-per-50{width:50% !important}.mj-column-px-150{width:150px !important}}</style><style type=\\"text/css\\"></style></head><body style=\\"background-color:#E5E5E5;\\"><div style=\\"background-color:#E5E5E5;\\"><div style=\\"background:#FFFFFF;background-color:#FFFFFF;Margin:0px auto;max-width:800px;\\"><table align=\\"center\\" border=\\"0\\" cellpadding=\\"0\\" cellspacing=\\"0\\" role=\\"presentation\\" style=\\"background:#FFFFFF;background-color:#FFFFFF;width:100%;\\"><tbody><tr><td style=\\"border-bottom:4px solid #e5e5e5;border-top:15px solid #E5E5E5;direction:ltr;font-size:0px;padding:15px 0;text-align:center;vertical-align:top;\\"><table align=\\"left\\" border=\\"0\\" cellpadding=\\"0\\" cellspacing=\\"0\\" role=\\"presentation\\" style=\\"border-collapse:collapse;border-spacing:0px;\\"><tbody><tr><td style=\\"padding:8px 6px\\"> <img  height=\\"auto\\" alt=\\"Direction g&eacute;n&eacute;rale des Finances publiques\\" src=\\"data:image/png;base64,\\" style=\\"border:0;display:block;outline:none;text-decoration:none;height:auto;width:100%;\\"></td></tr></tbody></table></td></tr></tbody></table></div><div style=\\"background:#FFFFFF;background-color:#FFFFFF;Margin:0px auto;max-width:800px;\\"><table role=\\"presentation\\" style=\\"background:#FFFFFF;background-color:#FFFFFF;width:100%;\\" cellspacing=\\"0\\" cellpadding=\\"0\\" border=\\"0\\" align=\\"center\\"><tbody><tr bgcolor=\\"#FFFFFF\\" align=\\"left\\"><td style=\\"font-family:Arial;color:#fff;padding-top:40px;\\"><p style=\\"color: #A63950; font-size: 2em; padding: 0em 25px .5em 25px;margin:0;line-height:1;\\">Consulter et payer votre avis d&rsquo;imp&ocirc;t 2026 de CFE et/ou d&rsquo;IFER depuis votre espace professionnel.</p></td></tr><tr><td style=\\"font-size:0px;padding:10px 25px;word-break:break-word;\\" align=\\"left\\"><div style=\\"font-family:Arial;font-size:14px;line-height:20px;text-align:left;color:#525252;\\"><p style=\\"color:#525252;\\">Bonjour,</p>\\n\\n<p style=\\"color:#525252;\\">Les avis d&rsquo;imp&ocirc;t 2026 de cotisation fonci&egrave;re des entreprises (CFE) et/ou d&rsquo;imposition forfaitaire sur les entreprises de r&eacute;seaux (IFER) sont disponibles dans votre espace professionnel sur le <strong>site Internet des imp&ocirc;ts.</strong></p>\\n\\n<p style=\\"color:#525252;\\">La date limite de paiement est fix&eacute;e au <strong>15 d&eacute;cembre 2026 inclus.</strong></p>\\n\\n<ul style=\\"color:#525252;\\">\\n\\t<li><u><strong>Comment consulter votre avis d&rsquo;imp&ocirc;t 2026 de CFE et/ou d&rsquo;IFER ?</strong></u></li>\\n</ul>\\n\\n<p style=\\"color:#525252;\\">D&egrave;s aujourd&rsquo;hui, connectez-vous &agrave; votre espace professionnel, s&eacute;lectionnez la rubrique &laquo;&nbsp;MES SERVICES &gt; Consulter &gt; Avis CFE&nbsp;&raquo;. Puis, cliquez simplement sur le lien &laquo;&nbsp;Acc&egrave;s aux avis de CFE&nbsp;&raquo; ou passez par le menu &laquo;&nbsp;ACC&Egrave;S PAR IMP&Ocirc;T &gt; Cotisation fonci&egrave;re des entreprises&nbsp;&raquo;.</p>\\n\\n<p style=\\"color:#525252;\\">Pour les entreprises ayant un seul &eacute;tablissement, vous pouvez consulter la vid&eacute;o disponible en ligne sur notre cha&icirc;ne Youtube en saisissant le libell&eacute;&nbsp;: <strong>&laquo;Comment consulter et payer sa CFE en ligne&nbsp;?&raquo;</strong> dans la barre de recherche.</p>\\n\\n<ul style=\\"color:#525252;\\">\\n\\t<li><u><strong>Comment payer votre cotisation de CFE et/ou d&rsquo;IFER 2026&nbsp;?</strong></u></li>\\n</ul>\\n\\n<p style=\\"color:#525252;\\">Pour payer cette &eacute;ch&eacute;ance, deux moyens de paiement d&eacute;mat&eacute;rialis&eacute; sont d&eacute;sormais autoris&eacute;s&nbsp;: le pr&eacute;l&egrave;vement automatique &agrave; l&rsquo;&eacute;ch&eacute;ance ou le paiement direct en ligne.</p>\\n\\n<p style=\\"color:#525252;\\">Pour cela, vous pouvez&nbsp;:</p>\\n\\n<ul style=\\"color:#525252;\\">\\n\\t<li>soit <strong>adh&eacute;rer au pr&eacute;l&egrave;vement automatique &agrave; l&rsquo;&eacute;ch&eacute;ance jusqu&rsquo;au 30 novembre 2026</strong>, sur le <strong>site Internet des imp&ocirc;ts</strong> ou par t&eacute;l&eacute;phone au 0 806 807 807 (accessible du lundi au vendredi de 8h30 &agrave; 18h, horaires de la m&eacute;tropole&nbsp;; service gratuit + prix de l&#39;appel). Vous r&eacute;glerez votre cotisation 2026 et n&rsquo;aurez plus &agrave; vous soucier de vos prochaines &eacute;ch&eacute;ances&nbsp;;</li>\\n\\t<li>soit <strong>payer directement en ligne jusqu&rsquo;au 15 d&eacute;cembre 2026 inclus</strong> en cliquant sur le bouton &laquo;&nbsp;Payer&nbsp;&raquo; situ&eacute; dans le tableau r&eacute;capitulatif des avis. Le ou les comptes bancaires que vous avez d&eacute;clar&eacute;s pr&eacute;alablement dans votre espace professionnel vous seront propos&eacute;s pour r&eacute;gler votre imposition. Le pr&eacute;l&egrave;vement sera effectu&eacute; apr&egrave;s la date limite de paiement.</li>\\n</ul>\\n\\n<p style=\\"color:#525252;\\">Si vous avez d&eacute;j&agrave; souscrit &agrave; un contrat de pr&eacute;l&egrave;vement automatique, vous n&rsquo;avez rien &agrave; faire.</p>\\n\\n<table class=\\"encadre\\" style=\\"border:2px solid #A63950;width:100%;\\">\\n\\t<tr>\\n\\t\\t<td style=\\"padding:15px;\\">\\n\\t\\t<p style=\\"color:#525252;\\"><strong>Comment cr&eacute;er votre espace professionnel&nbsp;:</strong></p>\\n\\n\\t\\t<p style=\\"color:#525252;\\">Rendez-vous sur le <strong>site Internet des imp&ocirc;ts,</strong> cliquez sur &laquo;&nbsp;Connexion &agrave; l&rsquo;espace professionnel&nbsp;&raquo; puis sur &laquo;&nbsp;Cr&eacute;er votre espace professionnel&nbsp;&raquo; et choisissez l&rsquo;option qui convient &agrave; vos besoins&nbsp;:</p>\\n\\n\\t\\t<p style=\\"color:#525252;\\">- en mode simplifi&eacute; si vous intervenez seul(e) sur cet espace pour le compte de votre entreprise,</p>\\n\\n\\t\\t<p style=\\"color:#525252;\\">- en mode expert si vous repr&eacute;sentez une entreprise ou intervenez pour le compte de plusieurs entreprises depuis cet espace.</p>\\n\\n\\t\\t<p style=\\"color:#525252;\\">En mode simplifi&eacute; et par s&eacute;curit&eacute;, un lien utilisable 72 heures maximum est envoy&eacute; imm&eacute;diatement par courriel &agrave; l&rsquo;adresse &eacute;lectronique d&eacute;clar&eacute;e afin d&rsquo;en v&eacute;rifier la validit&eacute; (v&eacute;rifiez vos spams ou pourriels).</p>\\n\\n\\t\\t<p style=\\"color:#525252;\\">Puis, apr&egrave;s v&eacute;rification de l&rsquo;adresse &eacute;lectronique, par mesure de s&eacute;curit&eacute;, un courrier contenant un code d&#39;activation valable 60 jours maximum vous sera automatiquement envoy&eacute; par voie postale.</p>\\n\\n\\t\\t<p style=\\"color:#525252;\\">&Agrave; r&eacute;ception, connectez-vous sans attendre &agrave; l&rsquo;espace professionnel, et cliquez sur &laquo;&nbsp;Activer&nbsp;&raquo;. &Agrave; l&rsquo;issue de cette d&eacute;marche, vous &ecirc;tes automatiquement habilit&eacute;(e) aux services de consultation et de paiement des imp&ocirc;ts et taxes et vous pouvez g&eacute;rer les services en ligne et la mise &agrave; jour des&nbsp;comptes&nbsp;bancaires.</p>\\n\\n\\t\\t<p style=\\"color:#525252;\\">Depuis votre espace professionnel, vous pouvez ainsi&nbsp;:<br />\\n\\t\\t- d&eacute;clarer et payer vos imp&ocirc;ts professionnels,<br />\\n\\t\\t- consulter vos donn&eacute;es fiscales,<br />\\n\\t\\t- effectuer des d&eacute;marches en ligne (par exemple, obtenir une attestation de r&eacute;gularit&eacute; fiscale ou une attestation de r&eacute;sidence fiscale),<br />\\n\\t\\t- consulter et payer votre avis de CFE et/ou d&rsquo;IFER,<br />\\n\\t\\t- poser vos questions gr&acirc;ce &agrave; votre messagerie s&eacute;curis&eacute;e.</p>\\n\\n\\t\\t<p style=\\"color:#525252;\\"><em>Pour plus de s&eacute;curit&eacute;, la DGFiP vous recommande de choisir un mot de passe et une r&eacute;ponse de confiance d&eacute;di&eacute;s &agrave; votre espace professionnel, dont les &eacute;l&eacute;ments ne peuvent pas &ecirc;tre identifi&eacute;s depuis vos r&eacute;seaux sociaux. Veillez &eacute;galement &agrave; utiliser une solution antivirus &agrave; jour, &agrave; ne pas enregistrer vos identifiants sur vos navigateurs web et &agrave; modifier vos identifiants et mots de passe d&#39;acc&egrave;s de tous vos terminaux (ordinateurs/tablettes/smartphones personnels et professionnels).</em></p>\\n\\t\\t</td>\\n\\t</tr>\\n</table>\\n\\n<p style=\\"color:#525252;text-align:center;\\"><strong>Toutes vos d&eacute;marches peuvent &ecirc;tre effectu&eacute;es en ligne</br>\\nsur le site Internet des imp&ocirc;ts (et sur le site Internet du portail pro si votre entreprise y est abonn&eacute;e).</strong></p>\\n\\n<p style=\\"color:#525252;\\">Pour toute demande concernant la consultation de l&rsquo;avis de CFE-IFER, ainsi que son paiement, vous pouvez contacter le <strong>0 806 807 807</strong> (service gratuit + prix de l&rsquo;appel) du <strong>lundi au vendredi de 8h30 &agrave; 18h</strong> (horaires de la m&eacute;tropole).</p>\\n\\n<p style=\\"color:#525252;\\">Nous vous remercions de votre attention.</p>\\n\\n<p style=\\"color:#525252;\\">&nbsp;</p>\\n<p style=\\"font-size:15px;margin-top:2em;color:#525252;\\"><b>La Direction g&eacute;n&eacute;rale des Finances publiques</b></p></div></td></tr></tbody></table></div><div style=\\"background:#FFFFFF;background-color:#FFFFFF;Margin:0px auto;max-width:800px;\\"><table role=\\"presentation\\" style=\\"background:#FFFFFF;background-color:#FFFFFF;width:100%;\\" cellspacing=\\"0\\" cellpadding=\\"0\\" border=\\"0\\" align=\\"center\\"><tbody><tr><td style=\\"direction:ltr;font-size:0px;padding:20px;text-align:center;vertical-align:top;\\"></td></tr></tbody></table></div><div style=\\"background:#E5E5E5;background-color:#E5E5E5;Margin:0px auto;max-width:800px;\\"><table role=\\"presentation\\" style=\\"background:#E5E5E5;background-color:#E5E5E5;width:100%;\\" cellspacing=\\"0\\" cellpadding=\\"0\\" border=\\"0\\" align=\\"center\\"><tbody><tr><td style=\\"direction:ltr;font-size:0px;padding:6px;text-align:center;vertical-align:top;\\"></td></tr></tbody></table></div><div style=\\"background:#f6f4f4;background-color:#f6f4f4;Margin:0px auto;max-width:800px;\\"><table role=\\"presentation\\" style=\\"background:#f6f4f4;background-color:#f6f4f4;width:100%;\\" cellspacing=\\"0\\" cellpadding=\\"0\\" border=\\"0\\" align=\\"center\\"><tbody><tr><td style=\\"direction:ltr;font-size:0px;padding:20px 0px 0px 0px;text-align:center;vertical-align:top;\\"><div class=\\"mj-column-per-100 outlook-group-fix\\" style=\\"font-size:13px;text-align:left;direction:ltr;display:inline-block;vertical-align:top;width:100%;\\"><table role=\\"presentation\\" style=\\"vertical-align:top;\\" width=\\"100%\\" cellspacing=\\"0\\" cellpadding=\\"0\\" border=\\"0\\"><tbody><tr><td align=left style=\\"font-size:0;padding:10px 25px;padding-bottom:0;word-break:break-word\\"><div style=\\"font-family:Arial;font-size:18px;line-height:1;text-align:left;color:#A63950\\">Services Publics +</div><tr><td align=left style=\\"font-size:0;padding:10px 25px;word-break:break-word\\"><div style=font-family:Arial,sans-serif;font-size:13px;line-height:1;text-align:left>Une hésitation pour une démarche ? Consultez la rubrique droit à l'erreur du site <b>transformation.gouv.fr</b><p> </div></tbody></table></div></td></tr></tbody></table></div><div style=\\"background:#E5E5E5;background-color:#E5E5E5;Margin:0px auto;max-width:800px;\\"><table role=\\"presentation\\" style=\\"background:#E5E5E5;background-color:#E5E5E5;width:100%;\\" cellspacing=\\"0\\" cellpadding=\\"0\\" border=\\"0\\" align=\\"center\\"><tbody><tr><td style=\\"direction:ltr;font-size:0px;padding:6px;text-align:center;vertical-align:top;\\"></td></tr></tbody></table></div><div style=\\"background:#f6f4f4;background-color:#f6f4f4;Margin:0px auto;max-width:800px;\\"><table role=\\"presentation\\" style=\\"background:#f6f4f4;background-color:#f6f4f4;width:100%;\\" cellspacing=\\"0\\" cellpadding=\\"0\\" border=\\"0\\" align=\\"center\\"><tbody><tr><td style=\\"direction:ltr;font-size:0px;padding:20px 0;text-align:center;vertical-align:top;\\"><div class=\\"mj-column-per-100 outlook-group-fix\\" style=\\"font-size:13px;text-align:left;direction:ltr;display:inline-block;vertical-align:top;width:100%;\\"><table role=\\"presentation\\" style=\\"vertical-align:top;\\" width=\\"100%\\" cellspacing=\\"0\\" cellpadding=\\"0\\" border=\\"0\\"><tbody><tr><td style=\\"font-size:0px;padding:10px 25px;padding-bottom:0;word-break:break-word;\\" align=\\"left\\"><div style=\\"font-family:Arial;font-size:18px;line-height:1;text-align:left;color:#A63950;\\">Savez-vous &agrave; quoi servent vos imp&ocirc;ts&nbsp;?</div></td></tr><tr><td style=\\"font-size:0px;padding:10px 25px;word-break:break-word;\\" align=\\"left\\"><div style=\\"font-family:Arial, sans-serif;font-size:13px;line-height:1;text-align:left;\\">D&eacute;couvrez-le sur le site <b>economie.gouv.fr</b>.</div></td></tr></tbody></table></div></td></tr></tbody></table></div><div style=\\"background:#E5E5E5;background-color:#E5E5E5;Margin:0px auto;max-width:800px;\\"><table role=\\"presentation\\" style=\\"background:#E5E5E5;background-color:#E5E5E5;width:100%;\\" cellspacing=\\"0\\" cellpadding=\\"0\\" border=\\"0\\" align=\\"center\\"><tbody><tr><td style=\\"direction:ltr;font-size:0px;padding:6px;text-align:center;vertical-align:top;\\"></td></tr></tbody></table></div><div style=\\"background:#F0F0F0;background-color:#F0F0F0;Margin:0px auto;max-width:800px;\\"><table role=\\"presentation\\" style=\\"background:#F0F0F0;background-color:#F0F0F0;width:100%;\\" cellspacing=\\"0\\" cellpadding=\\"0\\" border=\\"0\\" align=\\"center\\"><tbody><tr><td style=\\"direction:ltr;font-size:0px;padding:20px 0;text-align:center;vertical-align:top;\\"><div class=\\"mj-column-per-100 outlook-group-fix\\" style=\\"font-size:13px;text-align:left;direction:ltr;display:inline-block;vertical-align:top;width:100%;\\"><table role=\\"presentation\\" style=\\"vertical-align:top;\\" width=\\"100%\\" cellspacing=\\"0\\" cellpadding=\\"0\\" border=\\"0\\"><tbody><tr><td style=\\"font-size:0px;padding:10px 25px;padding-bottom:0;word-break:break-word;\\" align=\\"left\\"><div style=\\"font-family:Arial;font-size:18px;text-align:left;color:#BE2500;\\">Pour votre s&eacute;curit&eacute;&nbsp;:</div></td></tr><tr><td style=\\"font-size:0px;padding:10px 25px;word-break:break-word;\\" align=\\"left\\"><div style=\\"font-family:Arial, sans-serif;font-size:13px;text-align:left;\\"><ul><li><b>Ne r&eacute;pondez jamais</b> &agrave; un courriel vous demandant votre <b>num&eacute;ro de carte bancaire</b> ou une <b>copie de vos pi&egrave;ces d'identit&eacute;</b>.<br><br></li><li><b>Ne partagez jamais vos identifiants d'acc&egrave;s</b> &agrave; votre espace professionnel <b>DGFiP</b>, et pensez &agrave; <b>renouveler r&eacute;guli&egrave;rement votre mot de passe</b>.<br><br></li><li><b>V&eacute;rifiez toujours l'adresse de l'exp&eacute;diteur des messages avant de les ouvrir.</b> Pour la <b>DGFiP</b>, la partie droite de l'adresse doit &ecirc;tre &eacute;gale &agrave; <b>@dgfip.finances.gouv.fr</b> ou <b>@authentification.impots.gouv.fr</b>. Sinon, il s'agit d'un message frauduleux.</li></ul></div></td></tr></tbody></table></div></td></tr></tbody></table></div><div style=\\"background:#e5e5e5;background-color:#e5e5e5;Margin:0 auto;max-width:800px\\"><table border=0 cellpadding=0 cellspacing=0 role=presentation style=background:#e5e5e5;background-color:#e5e5e5;width:100% align=center><tr><td style=\\"direction:ltr;font-size:0;padding:20px 0;text-align:center;vertical-align:top\\"><div style=font-family:Arial,sans-serif;font-size:13px;line-height:1;text-align:center;color:#000>Retrouvez la <abbr title=\\"Direction générale des Finances publiques\\">DGFiP</abbr> sur :</div></table></div><div style=\\"background:#e5e5e5;background-color:#e5e5e5;Margin:0 auto;max-width:800px\\"><table border=0 cellpadding=0 cellspacing=0 role=presentation style=background:#e5e5e5;background-color:#e5e5e5;width:100% align=center><tr><td style=\\"direction:ltr;font-size:0;padding:20px 0;padding-bottom:50px;text-align:center;vertical-align:top\\"><div style=font-size:13px;text-align:left;direction:ltr;display:inline-block;vertical-align:top;width:110px class=\\"mj-column-px-150 outlook-group-fix\\"><table border=0 cellpadding=0 cellspacing=0 role=presentation style=vertical-align:top width=100%><tr><td style=font-size:0;padding:0;word-break:break-word align=center><table border=0 cellpadding=0 cellspacing=0 role=presentation style=border-collapse:collapse;border-spacing:0 align=center><tr><td style=width:45px><img  alt=\\"Linkedin\\" height=\\"auto\\" src=\\"data:image/png;base64,\\" style=\\"border:0;display:block;outline:0;text-decoration:none;width:100%\\" width=\\"45\\" title=\\"Visiter la page Linkedin de la DGFiP\\"></table><tr><td style=\\"font-size:0;padding:10px 25px;word-break:break-word\\"align=center><div style=font-family:Arial,sans-serif;font-size:13px;line-height:1;text-align:center;color:#000><span class=\\"reseaux\\" style=\\"text-decoration:none;color:#000\\" title=\\"Visiter la page Linkedin de la DGFiP\\">Linkedin</span></div></table></div><div style=font-size:13px;text-align:left;direction:ltr;display:inline-block;vertical-align:top;width:110px class=\\"mj-column-px-150 outlook-group-fix\\"><table border=0 cellpadding=0 cellspacing=0 role=presentation style=vertical-align:top width=100%><tr><td style=font-size:0;padding:0;word-break:break-word align=center><table border=0 cellpadding=0 cellspacing=0 role=presentation style=border-collapse:collapse;border-spacing:0 align=center><tr><td style=width:45px><img  alt=\\"Instagram\\" height=\\"auto\\" src=\\"data:image/png;base64,\\" style=\\"border:0;display:block;outline:0;text-decoration:none;width:100%\\" width=\\"45\\" title=\\"Visiter la page Instagram de la DGFiP\\"></table><tr><td style=\\"font-size:0;padding:10px 25px;word-break:break-word\\"align=center><div style=font-family:Arial,sans-serif;font-size:13px;line-height:1;text-align:center;color:#000><span class=\\"reseaux\\" style=\\"text-decoration:none;color:#000\\" title=\\"Visiter la page Instagram de la DGFiP\\">Instagram</span></div></table></div><div style=font-size:13px;text-align:left;direction:ltr;display:inline-block;vertical-align:top;width:110px class=\\"mj-column-px-150 outlook-group-fix\\"><table border=0 cellpadding=0 cellspacing=0 role=presentation style=vertical-align:top width=100%><tr><td style=font-size:0;padding:0;word-break:break-word align=center><table border=0 cellpadding=0 cellspacing=0 role=presentation style=border-collapse:collapse;border-spacing:0 align=center><tr><td style=width:45px><img  alt=\\"TikTok\\" height=\\"auto\\" src=\\"data:image/png;base64,\\" style=\\"border:0;display:block;outline:0;text-decoration:none;width:100%\\" width=\\"45\\" title=\\"Visiter la page TikTok de la DGFiP\\"></table><tr><td style=\\"font-size:0;padding:10px 25px;word-break:break-word\\"align=center><div style=font-family:Arial,sans-serif;font-size:13px;line-height:1;text-align:center;color:#000><span class=\\"reseaux\\" style=\\"text-decoration:none;color:#000\\" title=\\"Visiter la page TikTok de la DGFiP\\">TikTok</span></div></table></div><div style=font-size:13px;text-align:left;direction:ltr;display:inline-block;vertical-align:top;width:110px class=\\"mj-column-px-150 outlook-group-fix\\"><table border=0 cellpadding=0 cellspacing=0 role=presentation style=vertical-align:top width=100%><tr><td style=font-size:0;padding:0;word-break:break-word align=center><table border=0 cellpadding=0 cellspacing=0 role=presentation style=border-collapse:collapse;border-spacing:0 align=center><tr><td style=width:45px><img  alt=\\"X\\" height=\\"auto\\" src=\\"data:image/png;base64,\\" style=\\"border:0;display:block;outline:0;text-decoration:none;width:100%\\" width=\\"45\\" title=\\"Visiter la page X de la DGFiP\\"></table><tr><td style=\\"font-size:0;padding:10px 25px;word-break:break-word\\"align=center><div style=font-family:Arial,sans-serif;font-size:13px;line-height:1;text-align:center;color:#000><span class=\\"reseaux\\" style=\\"text-decoration:none;color:#000\\" title=\\"Visiter la page X de la DGFiP\\">X</span></div></table></div><div style=font-size:13px;text-align:left;direction:ltr;display:inline-block;vertical-align:top;width:110px class=\\"mj-column-px-150 outlook-group-fix\\"><table border=0 cellpadding=0 cellspacing=0 role=presentation style=vertical-align:top width=100%><tr><td style=font-size:0;padding:0;word-break:break-word align=center><table border=0 cellpadding=0 cellspacing=0 role=presentation style=border-collapse:collapse;border-spacing:0 align=center><tr><td style=width:45px><img  alt=\\"Facebook\\" height=\\"auto\\" src=\\"data:image/png;base64,\\" style=\\"border:0;display:block;outline:0;text-decoration:none;width:100%\\" width=\\"45\\" title=\\"Visiter la page Facebook de la DGFiP\\"></table><tr><td style=\\"font-size:0;padding:10px 25px;word-break:break-word\\"align=center><div style=font-family:Arial,sans-serif;font-size:13px;line-height:1;text-align:center;color:#000><span class=\\"reseaux\\" style=\\"text-decoration:none;color:#000\\" title=\\"Visiter la page Facebook de la DGFiP\\">Facebook</span></div></table></div></table></div>","Consulter et payer votre avis d’impôt 2026 de CFE et/ou d’IFER depuis votre espace professionnel.\\r\\n\\r\\nBonjour,\\n\\n\\n\\nLes avis d’impôt 2026 de cotisation foncière des entreprises (CFE) et/ou d’imposition forfaitaire sur les entreprises de réseaux (IFER) sont disponibles dans votre espace professionnel sur le site Internet des impôts.\\n\\n\\n\\nLa date limite de paiement est fixée au 15 décembre 2026 inclus.\\n\\n\\n\\n\\n\\t* Comment consulter votre avis d’impôt 2026 de CFE et/ou d’IFER ?\\n\\n\\n\\n\\nDès aujourd’hui, connectez-vous à votre espace professionnel, sélectionnez la rubrique « MES SERVICES > Consulter > Avis CFE ». Puis, cliquez simplement sur le lien « Accès aux avis de CFE » ou passez par le menu « ACCÈS PAR IMPÔT > Cotisation foncière des entreprises ».\\n\\n\\n\\nPour les entreprises ayant un seul établissement, vous pouvez consulter la vidéo disponible en ligne sur notre chaîne Youtube en saisissant le libellé : «Comment consulter et payer sa CFE en ligne ?» dans la barre de recherche.\\n\\n\\n\\n\\n\\t* Comment payer votre cotisation de CFE et/ou d’IFER 2026 ?\\n\\n\\n\\n\\nPour payer cette échéance, deux moyens de paiement dématérialisé sont désormais autorisés : le prélèvement automatique à l’échéance ou le paiement direct en ligne.\\n\\n\\n\\nPour cela, vous pouvez :\\n\\n\\n\\n\\n\\t* soit adhérer au prélèvement automatique à l’échéance jusqu’au 30 novembre 2026, sur le site Internet des impôts ou par téléphone au 0 806 807 807 (accessible du lundi au vendredi de 8h30 à 18h, horaires de la métropole ; service gratuit + prix de l'appel). Vous réglerez votre cotisation 2026 et n’aurez plus à vous soucier de vos prochaines échéances ;\\n\\n\\n\\t* soit payer directement en ligne jusqu’au 15 décembre 2026 inclus en cliquant sur le bouton « Payer » situé dans le tableau récapitulatif des avis. Le ou les comptes bancaires que vous avez déclarés préalablement dans votre espace professionnel vous seront proposés pour régler votre imposition. Le prélèvement sera effectué après la date limite de paiement.\\n\\n\\n\\n\\nSi vous avez déjà souscrit à un contrat de prélèvement automatique, vous n’avez rien à faire.\\n\\n\\n\\n\\n\\t\\n\\t\\t------ encadré (début)----------------------\\n\\n\\n\\t\\tComment créer votre espace professionnel :\\n\\n\\n\\n\\t\\tRendez-vous sur le site Internet des impôts, cliquez sur « Connexion à l’espace professionnel » puis sur « Créer votre espace professionnel » et choisissez l’option qui convient à vos besoins :\\n\\n\\n\\n\\t\\t- en mode simplifié si vous intervenez seul(e) sur cet espace pour le compte de votre entreprise,\\n\\n\\n\\n\\t\\t- en mode expert si vous représentez une entreprise ou intervenez pour le compte de plusieurs entreprises depuis cet espace.\\n\\n\\n\\n\\t\\tEn mode simplifié et par sécurité, un lien utilisable 72 heures maximum est envoyé immédiatement par courriel à l’adresse électronique déclarée afin d’en vérifier la validité (vérifiez vos spams ou pourriels).\\n\\n\\n\\n\\t\\tPuis, après vérification de l’adresse électronique, par mesure de sécurité, un courrier contenant un code d'activation valable 60 jours maximum vous sera automatiquement envoyé par voie postale.\\n\\n\\n\\n\\t\\tÀ réception, connectez-vous sans attendre à l’espace professionnel, et cliquez sur « Activer ». À l’issue de cette démarche, vous êtes automatiquement habilité(e) aux services de consultation et de paiement des impôts et taxes et vous pouvez gérer les services en ligne et la mise à jour des comptes bancaires.\\n\\n\\n\\n\\t\\tDepuis votre espace professionnel, vous pouvez ainsi :\\n\\n\\t\\t- déclarer et payer vos impôts professionnels,\\n\\n\\t\\t- consulter vos données fiscales,\\n\\n\\t\\t- effectuer des démarches en ligne (par exemple, obtenir une attestation de régularité fiscale ou une attestation de résidence fiscale),\\n\\n\\t\\t- consulter et payer votre avis de CFE et/ou d’IFER,\\n\\n\\t\\t- poser vos questions grâce à votre messagerie sécurisée.\\n\\n\\n\\n\\t\\tPour plus de sécurité, la DGFiP vous recommande de choisir un mot de passe et une réponse de confiance dédiés à votre espace professionnel, dont les éléments ne peuvent pas être identifiés depuis vos réseaux sociaux. Veillez également à utiliser une solution antivirus à jour, à ne pas enregistrer vos identifiants sur vos navigateurs web et à modifier vos identifiants et mots de passe d'accès de tous vos terminaux (ordinateurs/tablettes/smartphones personnels et professionnels).\\n\\n\\n\\t\\t------ encadré (fin) -----------------------\\n\\n\\n\\t\\n\\n\\nToutes vos démarches peuvent être effectuées en ligne\\n\\n\\n\\nsur le site Internet des impôts (et sur le site Internet du portail pro si votre entreprise y est abonnée).\\n\\n\\n\\nPour toute demande concernant la consultation de l’avis de CFE-IFER, ainsi que son paiement, vous pouvez contacter le 0 806 807 807 (service gratuit + prix de l’appel) du lundi au vendredi de 8h30 à 18h (horaires de la métropole).\\n\\n\\n\\nNous vous remercions de votre attention.\\n\\n\\n\\n \\n\\n\\n\\r\\n\\r\\nLa Direction générale des Finances publiques\\r\\n\\r\\n\\r\\n\\r\\nServices Publics +. Une hésitation pour une démarche ? Consultez la rubrique droit à l'erreur du site <b>transformation.gouv.fr</b>\\r\\n\\r\\n\\r\\n\\r\\nSavez-vous à quoi servent vos impôts? Découvrez-le sur le site economie.gouv.fr\\r\\n\\r\\n\\r\\n\\r\\nPour votre sécurité :\\r\\n\\r\\n- Ne répondez jamais à un courriel vous demandant votre numéro de carte bancaire ou une copie de vos pièces d'identité.\\r\\n\\r\\n- Ne partagez jamais vos identifiants d'accès à votre espace professionnel DGFiP, et pensez à renouveler régulièrement votre mot de passe.\\r\\n\\r\\n- Vérifiez toujours l'adresse de l'expéditeur des messages avant de les ouvrir. Pour la DGFiP, la partie droite de l'adresse doit être égale à @dgfip.finances.gouv.fr ou @authentification.impots.gouv.fr. Sinon, il s'agit d'un message frauduleux.\\r\\n\\r\\n\\r\\n\\r\\nRetrouvez la DGFiP sur Linkedin : Direction Générale des Finances Publiques, sur Instagram: Finances publiques, sur TikTok (@financespubliques), sur X (@dgfip_officiel) et sur Facebook : Direction Générale des Finances Publiques","<p>Consulter et payer votre avis d&rsquo;imp&ocirc;t 2026 de CFE et/ou d&rsquo;IFER depuis votre espace professionnel.</p><p>Bonjour,</p><p>Les avis d&rsquo;imp&ocirc;t 2026 de cotisation fonci&egrave;re des entreprises (CFE) et/ou d&rsquo;imposition forfaitaire sur les entreprises de r&eacute;seaux (IFER) sont disponibles dans votre espace professionnel sur le site Internet des imp&ocirc;ts.</p><p>La date limite de paiement est fix&eacute;e au 15 d&eacute;cembre 2026 inclus.</p><p>&#x9;* Comment consulter votre avis d&rsquo;imp&ocirc;t 2026 de CFE et/ou d&rsquo;IFER ?</p><p>D&egrave;s aujourd&rsquo;hui, connectez-vous &agrave; votre espace professionnel, s&eacute;lectionnez la rubrique &laquo;&nbsp;MES SERVICES &gt; Consulter &gt; Avis CFE&nbsp;&raquo;. Puis, cliquez simplement sur le lien &laquo;&nbsp;Acc&egrave;s aux avis de CFE&nbsp;&raquo; ou passez par le menu &laquo;&nbsp;ACC&Egrave;S PAR IMP&Ocirc;T &gt; Cotisation fonci&egrave;re des entreprises&nbsp;&raquo;.</p><p>Pour les entreprises ayant un seul &eacute;tablissement, vous pouvez consulter la vid&eacute;o disponible en ligne sur notre cha&icirc;ne Youtube en saisissant le libell&eacute;&nbsp;: &laquo;Comment consulter et payer sa CFE en ligne&nbsp;?&raquo; dans la barre de recherche.</p><p>&#x9;* Comment payer votre cotisation de CFE et/ou d&rsquo;IFER 2026&nbsp;?</p><p>Pour payer cette &eacute;ch&eacute;ance, deux moyens de paiement d&eacute;mat&eacute;rialis&eacute; sont d&eacute;sormais autoris&eacute;s&nbsp;: le pr&eacute;l&egrave;vement automatique &agrave; l&rsquo;&eacute;ch&eacute;ance ou le paiement direct en ligne.</p><p>Pour cela, vous pouvez&nbsp;:</p><p>&#x9;* soit adh&eacute;rer au pr&eacute;l&egrave;vement automatique &agrave; l&rsquo;&eacute;ch&eacute;ance jusqu&rsquo;au 30 novembre 2026, sur le site Internet des imp&ocirc;ts ou par t&eacute;l&eacute;phone au 0 806 807 807 (accessible du lundi au vendredi de 8h30 &agrave; 18h, horaires de la m&eacute;tropole&nbsp;; service gratuit + prix de l&apos;appel). Vous r&eacute;glerez votre cotisation 2026 et n&rsquo;aurez plus &agrave; vous soucier de vos prochaines &eacute;ch&eacute;ances&nbsp;;</p><p>&#x9;* soit payer directement en ligne jusqu&rsquo;au 15 d&eacute;cembre 2026 inclus en cliquant sur le bouton &laquo;&nbsp;Payer&nbsp;&raquo; situ&eacute; dans le tableau r&eacute;capitulatif des avis. Le ou les comptes bancaires que vous avez d&eacute;clar&eacute;s pr&eacute;alablement dans votre espace professionnel vous seront propos&eacute;s pour r&eacute;gler votre imposition. Le pr&eacute;l&egrave;vement sera effectu&eacute; apr&egrave;s la date limite de paiement.</p><p>Si vous avez d&eacute;j&agrave; souscrit &agrave; un contrat de pr&eacute;l&egrave;vement automatique, vous n&rsquo;avez rien &agrave; faire.</p><p>&#x9;<br/>&#x9;&#x9;------ encadr&eacute; (d&eacute;but)----------------------</p><p>&#x9;&#x9;Comment cr&eacute;er votre espace professionnel&nbsp;:</p><p>&#x9;&#x9;Rendez-vous sur le site Internet des imp&ocirc;ts, cliquez sur &laquo;&nbsp;Connexion &agrave; l&rsquo;espace professionnel&nbsp;&raquo; puis sur &laquo;&nbsp;Cr&eacute;er votre espace professionnel&nbsp;&raquo; et choisissez l&rsquo;option qui convient &agrave; vos besoins&nbsp;:</p><p>&#x9;&#x9;- en mode simplifi&eacute; si vous intervenez seul(e) sur cet espace pour le compte de votre entreprise,</p><p>&#x9;&#x9;- en mode expert si vous repr&eacute;sentez une entreprise ou intervenez pour le compte de plusieurs entreprises depuis cet espace.</p><p>&#x9;&#x9;En mode simplifi&eacute; et par s&eacute;curit&eacute;, un lien utilisable 72 heures maximum est envoy&eacute; imm&eacute;diatement par courriel &agrave; l&rsquo;adresse &eacute;lectronique d&eacute;clar&eacute;e afin d&rsquo;en v&eacute;rifier la validit&eacute; (v&eacute;rifiez vos spams ou pourriels).</p><p>&#x9;&#x9;Puis, apr&egrave;s v&eacute;rification de l&rsquo;adresse &eacute;lectronique, par mesure de s&eacute;curit&eacute;, un courrier contenant un code d&apos;activation valable 60 jours maximum vous sera automatiquement envoy&eacute; par voie postale.</p><p>&#x9;&#x9;&Agrave; r&eacute;ception, connectez-vous sans attendre &agrave; l&rsquo;espace professionnel, et cliquez sur &laquo;&nbsp;Activer&nbsp;&raquo;. &Agrave; l&rsquo;issue de cette d&eacute;marche, vous &ecirc;tes automatiquement habilit&eacute;(e) aux services de consultation et de paiement des imp&ocirc;ts et taxes et vous pouvez g&eacute;rer les services en ligne et la mise &agrave; jour des&nbsp;comptes&nbsp;bancaires.</p><p>&#x9;&#x9;Depuis votre espace professionnel, vous pouvez ainsi&nbsp;:</p><p>&#x9;&#x9;- d&eacute;clarer et payer vos imp&ocirc;ts professionnels,</p><p>&#x9;&#x9;- consulter vos donn&eacute;es fiscales,</p><p>&#x9;&#x9;- effectuer des d&eacute;marches en ligne (par exemple, obtenir une attestation de r&eacute;gularit&eacute; fiscale ou une attestation de r&eacute;sidence fiscale),</p><p>&#x9;&#x9;- consulter et payer votre avis de CFE et/ou d&rsquo;IFER,</p><p>&#x9;&#x9;- poser vos questions gr&acirc;ce &agrave; votre messagerie s&eacute;curis&eacute;e.</p><p>&#x9;&#x9;Pour plus de s&eacute;curit&eacute;, la DGFiP vous recommande de choisir un mot de passe et une r&eacute;ponse de confiance d&eacute;di&eacute;s &agrave; votre espace professionnel, dont les &eacute;l&eacute;ments ne peuvent pas &ecirc;tre identifi&eacute;s depuis vos r&eacute;seaux sociaux. Veillez &eacute;galement &agrave; utiliser une solution antivirus &agrave; jour, &agrave; ne pas enregistrer vos identifiants sur vos navigateurs web et &agrave; modifier vos identifiants et mots de passe d&apos;acc&egrave;s de tous vos terminaux (ordinateurs/tablettes/smartphones personnels et professionnels).</p><p>&#x9;&#x9;------ encadr&eacute; (fin) -----------------------</p><p>&#x9;</p><p>Toutes vos d&eacute;marches peuvent &ecirc;tre effectu&eacute;es en ligne</p><p>sur le site Internet des imp&ocirc;ts (et sur le site Internet du portail pro si votre entreprise y est abonn&eacute;e).</p><p>Pour toute demande concernant la consultation de l&rsquo;avis de CFE-IFER, ainsi que son paiement, vous pouvez contacter le 0 806 807 807 (service gratuit + prix de l&rsquo;appel) du lundi au vendredi de 8h30 &agrave; 18h (horaires de la m&eacute;tropole).</p><p>Nous vous remercions de votre attention.</p><p>&nbsp;</p><p>La Direction g&eacute;n&eacute;rale des Finances publiques</p><p>Services Publics +. Une h&eacute;sitation pour une d&eacute;marche ? Consultez la rubrique droit &agrave; l&apos;erreur du site &lt;b&gt;<a href=\\"http://transformation.gouv.fr\\">transformation.gouv.fr</a>&lt;/b&gt;</p><p>Savez-vous &agrave; quoi servent vos imp&ocirc;ts? D&eacute;couvrez-le sur le site <a href=\\"http://economie.gouv.fr\\">economie.gouv.fr</a></p><p>Pour votre s&eacute;curit&eacute; :</p><p>- Ne r&eacute;pondez jamais &agrave; un courriel vous demandant votre num&eacute;ro de carte bancaire ou une copie de vos pi&egrave;ces d&apos;identit&eacute;.</p><p>- Ne partagez jamais vos identifiants d&apos;acc&egrave;s &agrave; votre espace professionnel DGFiP, et pensez &agrave; renouveler r&eacute;guli&egrave;rement votre mot de passe.</p><p>- V&eacute;rifiez toujours l&apos;adresse de l&apos;exp&eacute;diteur des messages avant de les ouvrir. Pour la DGFiP, la partie droite de l&apos;adresse doit &ecirc;tre &eacute;gale &agrave; <a href=\\"https://twitter.com/dgfip\\">@dgfip</a>.finances.gouv.fr ou @authentification.impots.gouv.fr. Sinon, il s&apos;agit d&apos;un message frauduleux.</p><p>Retrouvez la DGFiP sur Linkedin : Direction G&eacute;n&eacute;rale des Finances Publiques, sur Instagram: Finances publiques, sur TikTok (@financespubliques), sur X (<a href=\\"https://twitter.com/dgfip_officiel\\">@dgfip_officiel</a>) et sur Facebook : Direction G&eacute;n&eacute;rale des Finances Publiques</p>","Vos avis d'impôt 2026 de CFE et/ou d'IFER sont disponibles dans votre espace professionnel sur le site Internet des impôts.","2026-11-03T08:47:53.000Z",{"value":"241","html":"242","text":"243"},{"value":"244","html":"245","text":"203"},"<20261103084753.2F03F86897@pf2pusi003.dgfip.finances.gouv.fr>",{"uid":2797},{"mimeType":"246","fileType":"247","fileExtension":"248","data":"249","id":"250","fileSize":"251","bytes":9963},{"mimeType":"246","fileType":"247","fileExtension":"248","data":"249","id":"252","fileSize":"253","bytes":1105},{"mimeType":"246","fileType":"247","fileExtension":"248","data":"249","id":"254","fileSize":"255","bytes":1727},{"mimeType":"246","fileType":"247","fileExtension":"248","data":"249","id":"256","fileSize":"257","bytes":1546},{"mimeType":"246","fileType":"247","fileExtension":"248","data":"249","id":"258","fileSize":"259","bytes":1466},{"mimeType":"246","fileType":"247","fileExtension":"248","data":"249","id":"260","fileSize":"261","bytes":1354},{"generations":"262"},{"completionTokens":119,"promptTokens":2817,"totalTokens":2936},["263"],{"anthropic_api_key":"264","model":"265","anthropic_api_url":"266","max_tokens":16384,"invocation_kwargs":"267","client_options":"268","streaming":false,"api_key":"269"},"```json\\n{\\n  \\"categorie\\": \\"administratif\\",\\n  \\"urgent\\": false,\\n  \\"resume\\": \\"La DGFIP informe de la disponibilité des avis d'impôt 2026 de CFE et/ou IFER dans l'espace professionnel. La date limite de paiement est fixée au 15 décembre 2026.\\",\\n  \\"auto_envoi_possible\\": false,\\n  \\"reponse_requise\\": false\\n}\\n```","administratif","La DGFIP informe de la disponibilité des avis d'impôt 2026 de CFE et/ou IFER dans l'espace professionnel. La date limite de paiement est fixée au 15 décembre 2026.","2026-11-03T08:47:00.000Z","\\"Direction Générale des Finances Publiques\\" <ne-pas-repondre@dgfip.finances.gouv.fr>","contact","2026-11-03T08:47:58.450Z","ne-pas-repondre@dgfip.finances.gouv.fr","Direction Générale des Finances Publiques","Consulter et payer votre avis d’impôt 2026 de CFE et/ou d’IFER depuis votre espace professionnel.\\r\\n\\r\\nBonjour,\\n\\n\\n\\nLes avis d’impôt 2026 de cotisation foncière des entreprises (CFE) et/ou d’imposition forfaitaire sur les entreprises de réseaux (IFER) sont disponibles dans votre espace professionnel sur le site Internet des impôts.\\n\\n\\n\\nLa date limite de paiement est fixée au 15 décembre 2026 inclus.\\n\\n\\n\\n\\n\\t* Comment consulter votre avis d’impôt 2026 de CFE et/ou d’IFER ?\\n\\n\\n\\n\\nDès aujourd’hui, connectez-vous à votre espace professionnel, sélectionnez la rubrique « MES SERVICES > Consulter > Avis CFE ». Puis, cliquez simplement sur le lien « Accès aux avis de CFE » ou passez par le menu « ACCÈS PAR IMPÔT > Cotisation foncière des entreprises ».\\n\\n\\n\\nPour les entreprises ayant un seul établissement, vous pouvez consulter la vidéo disponible en ligne sur notre chaîne Youtube en saisissant le libellé : «Comment consulter et payer sa CFE en ligne ?» dans la barre de recherche.\\n\\n\\n\\n\\n\\t* Comment payer votre cotisation de CFE et/ou d’IFER 2026 ?\\n\\n\\n\\n\\nPour payer cette échéance, deux moyens de paiement dématérialisé sont désormais autorisés : le prélèvement automatique à l’échéance ou le paiement direct en ligne.\\n\\n\\n\\nPour cela, vous pouvez :\\n\\n\\n\\n\\n\\t* soit adhérer au prélèvement automatique à l’échéance jusqu’au 30 novembre 2026, sur le site Internet des impôts ou par téléphone au 0 806 807 807 (accessible du lundi au vendredi de 8h30 à 18h, horaires de la métropole ; service gratuit + prix de l'appel). Vous réglerez votre cotisation 2026 et n’aurez plus à vous soucier de vos prochaines échéances ;\\n\\n\\n\\t* soit payer directement en ligne jusqu’au 15 décembre 2026 inclus en cliquant sur le bouton « Payer » situé dans le tableau récapitulatif des avis. Le ou les comptes bancaires que vous avez déclarés préalablement dans votre espace professionnel vous seront proposés pour régler votre imposition. Le prélèvement sera effectué après la date limite de paiement.\\n\\n\\n\\n\\nSi vous avez déjà souscrit à un contrat de prélèvement automatique, vous n’avez rien à faire.\\n\\n\\n\\n\\n\\t\\n\\t\\t------ encadré (début)----------------------\\n\\n\\n\\t\\tComment créer votre espace professionnel :\\n\\n\\n\\n\\t\\tRendez-vous sur le site Internet des impôts, cliquez sur « Connexion à l’espace professionnel » puis sur « Créer votre espace professionnel » et choisissez l’option qui convient à vos besoins :\\n\\n\\n\\n\\t\\t- en mode simplifié si vous intervenez seul(e) sur cet espace pour le compte de votre entreprise,\\n\\n\\n\\n\\t\\t- en mode expert si vous représen","2797","2026-11-03T08:47:58.501Z","Tri-Administratif","INBOX","1732048478",{},"Return-Path: <ne-pas-repondre@dgfip.finances.gouv.fr>","Delivered-To: contact@ebanista.fr","Received: from pf2pusi003.dgfip.finances.gouv.fr (pf2pusi003.dgfip.finances.gouv.fr [145.242.11.105])\\r\\n\\tby smtp-4-9000.mail.infomaniak.ch (Postfix) with ESMTPS id 4jJhzY48BpznFJ\\r\\n\\tfor <contact@ebanista.fr>; Tue,  3 Nov 2026 09:47:53 +0100 (CET)","Authentication-Results: mx.infomaniak.com; spf=pass smtp.mailfrom=dgfip.finances.gouv.fr","DKIM-Signature: v=1; a=rsa-sha256; c=relaxed/simple;\\r\\n\\td=dgfip.finances.gouv.fr; s=pf3; t=1793695673;\\r\\n\\tbh=5W6wzYVJOCHJwR/L7ViNj/1QrBo/EwaOLEIId+pf/Tw=;\\r\\n\\th=Date:To:Subject:From:From;\\r\\n\\tb=zw1swHLzdL2nJcHc/NUMJT/g9shjejo9vcSUE1JxG2pNq6yanbQBxEAAx4Bg7Wn7p\\r\\n\\t 3sxXGzrejP0UycBvxPT9+DegR4L5+iEC+DOr+F64d3tbqoU3Is6LzMunKAGyr/kSp+\\r\\n\\t iuxDQjck4IanjPINjxgNtUQY19vorfl+pEh0DhTAterAzRWpq07+zljiXlPz8C6Hbf\\r\\n\\t rOmeONP77dMCp3030yrnF2t/mi8OJaCwud6yVXtET2OpUhETFxhdT1HMaCJhwWIvIJ\\r\\n\\t 4g6HngdpopnkEsKNU+MKgwOiE9bnjluFT12DEwoQ2RPbIvOl3efhVJz3w5LADNe73D\\r\\n\\t uqrovhatuyPZA==","DKIM-Filter: OpenDKIM Filter v2.11.0 pf3pgsi006-a.pfz3 4jJhzY0QmhzMqRHw","Content-Transfer-Encoding: binary","Content-Type: multipart/alternative; boundary=\\"_----------=_17936956733651693162806\\"","MIME-Version: 1.0","Date: Tue, 3 Nov 2026 09:47:53 +0100","To: contact@ebanista.fr\\r\\n ","Subject: =?UTF-8?Q?Vos_avis_d=27imp=c3=b4t_2026_de_CFE_et=2fou_d=27IFER_sont_disponibles_dans_votre_espace_professionnel_sur_le_site_Internet_des_imp=c3=b4ts=2e?=","From: =?UTF-8?Q?Direction_G=c3=a9n=c3=a9rale_des_Finances_Publiques?=<ne-p