CIAL_2%20%20&utm_medium=email&utm_source=Eloqua&s=602638917&lid=13511&elqTrackId=D970799769239168C1ABE1AA7471E188&elq=1ce943638ee34d899deaff026080deaa&elqaid=17160&elqat=1&elqak=8AF5F9CDA696614DE9A3D47A1070B487B6070C4D47B5232181E96FA2547A88CE7396>                                                               \\n\\nEntreprise sans client assujetti à la TVA : quid de l’émission de factures électroniques ?\\n\\nDe nombreuses entreprises ne livrent ou ne servent que des particuliers (autrement appelés « consommateurs »). Soit elles gèrent leurs ventes via une caisse, soit elles établissent des factures. Dans ce cas, sont-elles tenues d’émettre des factures électroniques ? Si la réponse est négative, doivent-elles obligatoirement se doter d’un logiciel de facturation ? ➡️ Lire la suite <https://app.infos.fiducial.fr/e/er?utm_campaign=102026_Newsletter_FIDUCIAL_2%20%20&utm_medium=email&utm_source=Eloqua&s=602638917&lid=13511&elqTrackId=4DA20DE435C506A68CC7B3492475AE58&elq=1ce943638ee34d899deaff026080deaa&elqaid=17160&elqat=1&elqak=8AF5CF59963A26AFEB29CE5A1BAA1EAB679A0C4D47B5232181E96FA2547A88CE7396>\\n\\n \\n\\n<https://app.infos.fiducial.fr/e/er?utm_campaign=102026_Newsletter_FIDUCIAL_2%20%20&utm_medium=email&utm_source=Eloqua&s=602638917&lid=43&elqTrackId=F6ADDD7F5A3F522C21ECA9DDED5F53E0&elq=1ce943638ee34d899deaff026080deaa&elqaid=17160&elqat=1&elqak=8AF5C1B464D65DC89657EE8334B6C4E6E9640C4D47B5232181E96FA2547A88CE7396>                        \\n\\n<https://app.infos.fiducial.fr/e/er?utm_campaign=102026_Newsletter_FIDUCIAL_2%20%20&utm_medium=email&utm_source=Eloqua&s=602638917&lid=591&elqTrackId=18FB47D910515EBAA265AE565FDCB021&elq=1ce943638ee34d899deaff026080deaa&elqaid=17160&elqat=1&elqak=8AF58C2FEE938C6C56871E12BB37512BC2290C4D47B5232181E96FA2547A88CE7396>                        \\n\\n<https://app.infos.fiducial.fr/e/er?utm_campaign=102026_Newsletter_FIDUCIAL_2%20%20&utm_medium=email&utm_source=Eloqua&s=602638917&lid=7616&elqTrackId=6A74E032541B654D8E9A01ACD42FD96B&elq=1ce943638ee34d899deaff026080deaa&elqaid=17160&elqat=1&elqak=8AF52BDE4049EB89D03B792A2D149F794C550C4D47B5232181E96FA2547A88CE7396>                        \\n\\n<https://app.infos.fiducial.fr/e/er?utm_campaign=102026_Newsletter_FIDUCIAL_2%20%20&utm_medium=email&utm_source=Eloqua&s=602638917&lid=7615&elqTrackId=2C2987611A2CAA63E2A06334497A8996&elq=1ce943638ee34d899deaff026080deaa&elqaid=17160&elqat=1&elqak=8AF56BF61C7405EBBD3F336923FA30A8EF930C4D47B5232181E96FA2547A88CE7396>                        \\n\\n<https://app.infos.fiducial.fr/e/er?utm_campaign=102026_Newsletter_FIDUCIAL_2%20%20&utm_medium=email&utm_source=Eloqua&s=602638917&lid=43&elqTrackId=A20E9D62891D3B729E29688DB9C1EAA5&elq=1ce943638ee34d899deaff026080deaa&elqaid=17160&elqat=1&elqak=8AF5954F4B397E20B469F78EE55A331095FA0C4D47B5232181E96FA2547A88CE7396>                                                               \\n\\n<https://app.infos.fiducial.fr/e/er?utm_campaign=102026_Newsletter_FIDUCIAL_2%20%20&utm_medium=email&utm_source=Eloqua&s=602638917&lid=591&elqTrackId=9D513FD422EEF3D2C4F1191D8DD1B33D&elq=1ce943638ee34d899deaff026080deaa&elqaid=17160&elqat=1&elqak=8AF5E920E1A43AAF91F4F3573AA3E94F38760C4D47B5232181E96FA2547A88CE7396>                                                               \\n\\n<https://app.infos.fiducial.fr/e/er?utm_campaign=102026_Newsletter_FIDUCIAL_2%20%20&utm_medium=email&utm_source=Eloqua&s=602638917&lid=7616&elqTrackId=79D1CF0D77BD5D794F355F1F22344974&elq=1ce943638ee34d899deaff026080deaa&elqaid=17160&elqat=1&elqak=8AF5C443BEBB957319E2AC2F429311746CA00C4D47B5232181E96FA2547A88CE7396>                                                               \\n\\n<https://app.infos.fiducial.fr/e/er?utm_campaign=102026_Newsletter_FIDUCIAL_2%20%20&utm_medium=email&utm_source=Eloqua&s=602638917&lid=7615&elqTrackId=AD5B040F71B812346A54C1DF0CC89438&elq=1ce943638ee34d899deaff026080deaa&elqaid=17160&elqat=1&elqak=8AF5A4B22DD01D07595395561052D174F7F50C4D47B5232181E96FA2547A88CE7396>                                                               \\n\\n\\n\\n\\nVous bénéficiez d'un droit d'accès, de rectification, d'effacement et de portabilité des données vous concernant, ainsi qu'un droit de limitation et d'opposition à leur traitement. En savoir plus <https://www.fiducial.fr/Politique-de-confidentialite?utm_campaign=102026_Newsletter_FIDUCIAL_2%20%20&utm_medium=email&utm_source=Eloqua&xtor=ES-10000-[_617]---10752@1--&elqTrackId=3f4cfb3139344558a54bb3caafdf4c01&elqak=8AF586C048CC0E136495417E245C45E1C439A6998328A55187C3D94ED489F3D97176>\\n\\nSi vous ne souhaitez plus recevoir d'e-mail de notre part, cliquez ici <https://news.fiducial.fr/gestion-abonnement-FIDEXP/comptabiliteL8PCV6?utm_campaign=102026_Newsletter_FIDUCIAL_2%20%20&utm_medium=email&utm_source=Eloqua&fidexp=Ancien%20Client&elqTrackId=a63caf4fe2ec4231809db811f9712852&elq=1ce943638ee34d899deaff026080deaa&elqaid=17160&elqat=1&elqCampaignId=12952&elqak=8AF50E55E1A2C1197A309BEBDC350D8308F90C4D47B5232181E96FA2547A88CE7396>                         \\n\\n\\n",{"lc":1,"type":"222","id":"223"},"claude-sonnet-4-6","https://api.anthropic.com",{},{"fetchOptions":"224"},{"lc":1,"type":"222","id":"225"},{"address":"203","name":"226"},{"address":"227","name":"228"},{"address":"229","name":"230"},["231"],"secret",["232"],{},["232"],"","contact@infos.fiducial.fr","Newsletter FIDUCIAL","contact.marketing@fiducial.fr","FIDUCIAL",{"text":"160"},"ANTHROPIC_API_KEY"]	b24ff535-dba4-49f6-a639-0e6a29640469
