nt-size:10.0pt;\\n\\tfont-family:Wingdings;}\\n@list l1:level9\\n\\t{mso-level-number-format:bullet;\\n\\tmso-level-text:;\\n\\tmso-level-tab-stop:324.0pt;\\n\\tmso-level-number-position:left;\\n\\ttext-indent:-18.0pt;\\n\\tmso-ansi-font-size:10.0pt;\\n\\tfont-family:Wingdings;}\\nol\\n\\t{margin-bottom:0cm;}\\nul\\n\\t{margin-bottom:0cm;}\\n--></style><!--[if gte mso 9]><xml>\\n<o:shapedefaults v:ext=\\"edit\\" spidmax=\\"1026\\" />\\n</xml><![endif]--><!--[if gte mso 9]><xml>\\n<o:shapelayout v:ext=\\"edit\\">\\n<o:idmap v:ext=\\"edit\\" data=\\"1\\" />\\n</o:shapelayout></xml><![endif]-->\\n</head>\\n<body lang=\\"FR\\" link=\\"blue\\" vlink=\\"purple\\" style=\\"word-wrap:break-word\\">\\n<div class=\\"WordSection1\\">\\n<p class=\\"MsoNormal\\"><span style=\\"font-size:11.0pt;mso-fareast-language:EN-US\\">Bonjour<o:p></o:p></span></p>\\n<p class=\\"MsoNormal\\"><span style=\\"font-size:11.0pt;mso-fareast-language:EN-US\\">Je vous donne une réponse dans l’après-midi (mais à priori ok le 04/11 à 8h)<o:p></o:p></span></p>\\n<p class=\\"MsoNormal\\"><span style=\\"font-size:11.0pt;mso-fareast-language:EN-US\\">Merci\\n<o:p></o:p></span></p>\\n<p class=\\"MsoNormal\\"><span style=\\"font-size:11.0pt;mso-fareast-language:EN-US\\"><o:p>&nbsp;</o:p></span></p>\\n<div>\\n<p class=\\"MsoNormal\\"><span style=\\"font-size:11.0pt\\"><img width=\\"257\\" height=\\"116\\" style=\\"width:2.6805in;height:1.2083in\\" id=\\"Image_x0020_4\\" src=\\"data:image/png;base64,\\"><o:p></o:p></span></p>\\n</div>\\n<p class=\\"MsoNormal\\"><span style=\\"font-size:11.0pt;mso-fareast-language:EN-US\\"><o:p>&nbsp;</o:p></span></p>\\n<div>\\n<div style=\\"border:none;border-top:solid #E1E1E1 1.0pt;padding:3.0pt 0cm 0cm 0cm\\">\\n<p class=\\"MsoNormal\\"><b><span style=\\"font-size:11.0pt;font-family:&quot;Calibri&quot;,sans-serif\\">De&nbsp;:</span></b><span style=\\"font-size:11.0pt;font-family:&quot;Calibri&quot;,sans-serif\\"> lsauzade@unitecheu.com &lt;lsauzade@unitecheu.com&gt;\\n<br>\\n<b>Envoyé&nbsp;:</b> mardi 27 octobre 2026 16:52<br>\\n<b>À&nbsp;:</b> IGNACIO Richard &lt;richard.ignacio@edf.fr&gt;; DI-TOMMASO Patrick &lt;patrick.di-tommaso@edf.fr&gt;; FORT Magali &lt;magali.fort@edf.fr&gt;<br>\\n<b>Cc&nbsp;:</b> PIGUET Christophe &lt;christophe.piguet@edf.fr&gt;; LOYEN Alban &lt;alban.loyen@edf.fr&gt;; COLLADO Lucas &lt;lucas.collado@edf.fr&gt;; BLEMY Jeannick &lt;jeannick-j.malsa@edf.fr&gt;; L. Vallee - UniTech &lt;lvallee@unitecheu.com&gt;; Caufriez Valentin &lt;v.caufriez@ebanista.fr&gt;<br>\\n<b>Objet&nbsp;:</b> RE: Conteneurs EDF AMT VDR - Proposition date pour clarifications techniques<o:p></o:p></span></p>\\n</div>\\n</div>\\n<p class=\\"MsoNormal\\"><o:p>&nbsp;</o:p></p>\\n<table class=\\"MsoNormalTable\\" border=\\"1\\" cellspacing=\\"3\\" cellpadding=\\"0\\" width=\\"100%\\" style=\\"width:100.0%;background:#F1DDA5;border:solid red 1.0pt\\">\\n<tbody>\\n<tr>\\n<td style=\\"border:none;padding:.75pt .75pt .75pt .75pt\\">\\n<p class=\\"MsoNormal\\" align=\\"center\\" style=\\"text-align:center\\"><strong><span style=\\"font-size:10.5pt;font-family:&quot;Aptos&quot;,sans-serif;color:red\\">Expéditeur externe :</span></strong><span style=\\"color:black\\">\\n</span><span style=\\"font-size:9.0pt;color:black\\">Vérifier l’expéditeur avant de cliquer sur les liens ou pièces-jointes</span><o:p></o:p></p>\\n</td>\\n</tr>\\n<tr>\\n<td style=\\"border:none;padding:.75pt .75pt .75pt .75pt\\">\\n<p class=\\"MsoNormal\\" align=\\"center\\" style=\\"text-align:center\\"><strong><span style=\\"font-size:10.5pt;font-family:&quot;Aptos&quot;,sans-serif;color:red\\">External Sender :\\n</span></strong><span style=\\"font-size:9.0pt;color:black\\">Check the sender before clicking any links or attachments</span><o:p></o:p></p>\\n</td>\\n</tr>\\n</tbody>\\n</table>\\n<p class=\\"MsoNormal\\"><span style=\\"font-size:11.0pt;font-family:&quot;Trebuchet MS&quot;,sans-serif;color:black\\">Bonjour à tous,<o:p></o:p></span></p>\\n<p class=\\"MsoNormal\\"><span style=\\"font-size:11.0pt;font-family:&quot;Trebuchet MS&quot;,sans-serif;color:black\\"><o:p>&nbsp;</o:p></span></p>\\n<p class=\\"MsoNormal\\"><span style=\\"font-size:11.0pt;font-family:&quot;Trebuchet MS&quot;,sans-serif;color:black\\"><o:p>&nbsp;</o:p></span></p>\\n<p class=\\"MsoNormal\\"><span style=\\"font-size:11.0pt;font-family:&quot;Trebuchet MS&quot;,sans-serif;color:black\\">Selon les échanges constructifs lors de la Réunion d'enclenchement du 22/09, nous avons finalisé les plans de vos 2 conteneurs.<o:p></o:p></span></p>\\n<p class=\\"MsoNormal\\"><span style=\\"font-size:11.0pt;font-family:&quot;Trebuchet MS&quot;,sans-serif;color:black\\">Nous aimerions vous les présenter et balayer encore certains points restants sans réponse, notamment :<o:p></o:p></span></p>\\n<p class=\\"MsoNormal\\"><span style=\\"font-size:11.0pt;font-family:&quot;Trebuchet MS&quot;,sans-serif;color:black\\"><o:p>&nbsp;</o:p></span></p>\\n<div>\\n<ul style=\\"margin-top:0cm\\" type=\\"disc\\">\\n<li class=\\"MsoNormal\\" style=\\"color:black;mso-list:l0 level1 lfo1\\"><span style=\\"font-size:11.0pt;font-family:&quot;Trebuchet MS&quot;,sans-serif\\">Décision finale quant à la destination du groupe extérieur<o:p></o:p></span></li></ul>\\n</div>\\n<div>\\n<ul style=\\"margin-top:0cm\\" type=\\"disc\\">\\n<li class=\\"MsoNormal\\" style=\\"color:black;mso-list:l0 level1 lfo1\\"><span style=\\"font-size:11.0pt;font-family:&quot;Trebuchet MS&quot;,sans-serif\\">Extincteur : Limites de prestation, pas de notre compétence<o:p></o:p></span></li></ul>\\n</div>\\n<div>\\n<ul style=\\"margin-top:0cm\\" type=\\"disc\\">\\n<li class=\\"MsoNormal\\" style=\\"color:black;mso-list:l0 level1 lfo1\\"><span style=\\"font-size:11.0pt;font-family:&quot;Trebuchet MS&quot;,sans-serif\\">Armoire électrique : Avez-vous des dimensions en tête ? Que prévoyez-vous de mettre dedans ?<o:p></o:p></span></li></ul>\\n</div>\\n<p class=\\"MsoNormal\\"><span style=\\"font-size:11.0pt;font-family:&quot;Trebuchet MS&quot;,sans-serif;color:black\\"><o:p>&nbsp;</o:p></span></p>\\n<p class=\\"MsoNormal\\"><span style=\\"font-size:11.0pt;font-family:&quot;Trebuchet MS&quot;,sans-serif;color:black\\"><o:p>&nbsp;</o:p></span></p>\\n<p class=\\"MsoNormal\\"><span style=\\"font-size:11.0pt;font-family:&quot;Trebuchet MS&quot;,sans-serif;color:black\\">Voici les créneaux auxquels Valentin CAUFRIEZ, notre aménageur EBANISTA et moi-même sommes disponibles :<o:p></o:p></span></p>\\n<p class=\\"MsoNormal\\"><span style=\\"font-size:11.0pt;font-family:&quot;Trebuchet MS&quot;,sans-serif;color:black\\">Nous suggérons un RDV Teams, mais nous pouvons également nous déplacer dans vos locaux ou vous-mêmes revenir à VALAURIE.&nbsp;<o:p></o:p></span></p>\\n<p class=\\"MsoNormal\\"><span style=\\"font-size:11.0pt;font-family:&quot;Trebuchet MS&quot;,sans-serif;color:black\\"><o:p>&nbsp;</o:p></span></p>\\n<p class=\\"MsoNormal\\"><span style=\\"font-size:11.0pt;font-family:&quot;Trebuchet MS&quot;,sans-serif;color:black\\"><o:p>&nbsp;</o:p></span></p>\\n<table class=\\"MsoNormalTable\\" border=\\"0\\" cellspacing=\\"0\\" cellpadding=\\"0\\" style=\\"border-collapse:collapse;box-sizing: border-box;border-spacing: 0px\\" id=\\"table_0\\">\\n<tbody>\\n<tr style=\\"height:30.55pt\\">\\n<td width=\\"276\\" style=\\"width:207.2pt;border:solid black 1.0pt;padding:.75pt 5.4pt .75pt 5.4pt;height:30.55pt;min-width: 15px;box-sizing: border-box\\">\\n<p class=\\"MsoNormal\\" align=\\"center\\" style=\\"margin-bottom:.75pt;text-align:center\\">\\n<b><span style=\\"font-size:11.0pt;font-family:&quot;Trebuchet MS&quot;,sans-serif\\">CRENEAUX DE DISPONIBILITÉS UNITECH</span></b><span style=\\"font-size:11.0pt;font-family:&quot;Trebuchet MS&quot;,sans-serif\\"><o:p></o:p></span></p>\\n</td>\\n<td width=\\"162\\" style=\\"width:121.85pt;border:solid black 1.0pt;border-left:none;padding:.75pt 5.4pt .75pt 5.4pt;height:30.55pt;min-width: 15px;box-sizing: border-box\\">\\n<p class=\\"MsoNormal\\" align=\\"center\\