re_fournisseur: 'Tri-Offre fournisseur',\\n  confirmation_commande: 'Tri-Confirmation de commande',\\n  prospects: 'Tri-Prospects',\\n  suivi_client: 'Tri-SuiviClient',\\n  administratif: 'Tri-Administratif',\\n  litige: 'Tri-Litige',\\n  facturation: 'Tri-Facturation',\\n  spam: 'Spam'\\n};\\n\\n// Traite TOUS les mails d'un lot (plusieurs mails peuvent arriver en même temps)\\nreturn $input.all().map((entry, i) => {\\n  const item = entry.json;\\n  const targetFolder = folderMap[item.categorie] || 'Tri-Administratif';\\n  // Pas de réponse automatique sur cette boîte : seul le spam est marqué lu.\\n  const markAsRead = item.categorie === 'spam';\\n  return { json: { ...item, targetFolder, markAsRead }, pairedItem: { item: i } };\\n});"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1344,288],"id":"f1a1b111-0000-4000-8000-000000000020","name":"Déterminer dossier cible"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"moveEmail","sourceMailbox":{"__rl":true,"mode":"path","value":"INBOX"},"emailUid":"={{ $('Email Trigger (IMAP)').item.json.attributes.uid }}","destinationMailbox":{"__rl":true,"mode":"path","value":"={{ $('Déterminer dossier cible').item.json.targetFolder }}"}},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[1568,288],"id":"f1a1b111-0000-4000-8000-000000000021","name":"Déplacer le mail","credentials":{"imap":{"id":"TkTrXXrbgNbUWRld","name":"IMAP - comptabilite@ebanista.fr"}}},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"f1a1b111-0000-4000-8000-00000000f003","leftValue":"={{ $json.markAsRead }}","rightValue":"","operator":{"type":"boolean","operation":"true","singleValue":true}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1568,200],"id":"f1a1b111-0000-4000-8000-000000000022","name":"Faut-il marquer lu ?"},{"parameters":{"authentication":"coreImapAccount","resource