ue && mail.from.value[0]) || {};\\n  return {\\n    json: {\\n      from_address: from.address || '',\\n      from_name: from.name || '',\\n      subject: mail.subject || '',\\n      text: mail.text || '',\\n      date: mail.date || '',\\n      message_id: mail.messageId || '',\\n      resume: entry.json.resume || '',\\n      categorie: entry.json.categorie || '',\\n    },\\n    pairedItem: { item: i },\\n  };\\n});\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1792,-544],"id":"d2000000-0000-4000-8000-000000000042","name":"Préparer données brouillon"},{"parameters":{"source":"database","workflowId":{"__rl":true,"value":"705Af47ZTs7QhMZd","mode":"id"},"mode":"each","options":{"waitForSubWorkflow":false}},"type":"n8n-nodes-base.executeWorkflow","typeVersion":1.1,"position":[2016,-544],"id":"d2000000-0000-4000-8000-000000000043","name":"Rédiger un brouillon de réponse","onError":"continueRegularOutput"}]	{"Anthropic Chat Model":{"ai_languageModel":[[{"node":"Basic LLM Chain","type":"ai_languageModel","index":0}]]},"Email Trigger (IMAP)":{"main":[[{"node":"Basic LLM Chain","type":"main","index":0}]]},"Basic LLM Chain":{"main":[[{"node":"Code in JavaScript","type":"main","index":0}]]},"Code in JavaScript":{"main":[[{"node":"Filtrer spam","type":"main","index":0},{"node":"Déterminer dossier cible","type":"main","index":0}]]},"If":{"main":[[{"node":"Send a text message","type":"main","index":0}],[]]},"Filtrer spam":{"main":[[{"node":"If","type":"main","index":0},{"node":"Insert row","type":"main","index":0},{"node":"Réponse à préparer ?","type":"main","index":0}]]},"Déterminer dossier cible":{"main":[[{"node":"Faut-il marquer lu ?","type":"main","index":0}]]},"Faut-il marquer lu ?":{"main":[[{"node":"Marquer comme lu","type":"main","index":0}],[{"node":"Déplacer le mail","type":"main","index":0}]]},"Marquer comme lu":{"main":[[{"node":"Attendre 8s","type":"main","index":0}]]},"Attendre 8s":{"main":[[{"node":"Déplacer le mail","type":"main","index":0}]]},"Réponse à préparer ?":{"main":[[{"node":"Préparer données brouillon","type":"main","index":0}],[]]},"Préparer données brouillon":{"main":[[{"node":"Rédiger un brouillon de réponse","type":"main","index":0}]]}}	\N	f	\N	[]
39565b03-cc14-42aa-8ef6-9b94ee500591	rdwd6bujINDV6M7U	Valentin Caufriez	2026-10-09 20:20:49.379+00	2026-10-09 20:20:49.379+00	[{"parameters":{"rule":{"interval":[{"field":"cronExpression","expression":"0 4 * * *"}]}},"type":"n8n-nodes-base.scheduleTrigger","typeVersion":1.2,"position":[0,0],"id":"da88aa7d-1723-409c-ac04-84529c05fa01","name":"Chaque nuit à 4h"},{"parameters":{"method":"DELETE","url":"http://localhost:5678/api/v1/data-tables/xhFI6TwJikamYjPL/rows/delete","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","sendQuery":true,"queryParameters":{"parameters":[{"name":"filter","value":"={{ JSON.stringify({ type: 'and', filters: [{ columnName: 'recu_le', condition: 'lt', value: $now.minus({ days: 45 }).toUTC().toISO() }] }) }}"}]},"options":{}},"type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[260,0],"id":"93f687ee-ad11-424c-8368-99e84c999d73","name":"Supprimer les mails de plus de 45 jours","credentials":{"httpHeaderAuth":{"id":"Lfuh7XFXewkeDjJe","name":"n8n API Key (interne)"}}}]	{"Chaque nuit à 4h":{"main":[[{"node":"Supprimer les mails de plus de 45 jours","type":"main","index":0}]]}}	\N	f	\N	[]
20d95c4a-0c8e-40e3-8dea-1d5485e5ad05	dAXiYGhwrnLjIbHU	Valentin Caufriez	2026-10-09 19:26:08.186+00	2026-10-09 19:26:08.186+00	[{"parameters":{"inputSource":"passthrough"},"type":"n8n-nodes-base.executeWorkflowTrigger","typeVersion":1.1,"position":[0,0],"id":"a1000000-0000-4000-8000-000000000001","name":"Entrée sous-workflow"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"getEmailsList","mailboxPath":{"__rl":true,"mode":"path","value":"Sent"},"emailDateRange":{"since":"={{ $now.minus({ years: 1 }).toISO() }}"},"emailSearchFilters":{"to":"={{ $json.from_address || 'adresse-introuvable@invalid.invalid' }}"},"limit":40,"includeParts":["textContent"]},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[260,0],"id":"a1000000-0000-4000-8000-000000000002","name":"Retrouver mes réponses précédentes","alwaysOutputData":true,"onError":"continueRegularOutput","credentials":{"imap":{"id":"nFnyy1qJ60BZTKsw","name":"IMAP - contact@ebanista.fr"}}},{"parameters":{"jsCode":"// Assemble le prompt : mail reçu + historique des réponses précédentes à ce correspondant\\nconst src = $('Entrée sous-workflow').first().json;\\nconst found = $input.all().map(i => i.json).filter(j => j && j.envelope && !j.error);\\n\\nconst ownText = (t) => String(t || '').replace(/\\\\r/g, '')\\n  .split(/\\\\n(?:>|Le .{5,90} a écrit|De ?:|From:|-----Original|On .{5,90} wrote)/)[0].trim();\\n\\nconst history = found\\n  .map(j => ({ date: new Date(j.envelope.date || 0), subject: j.envelope.subject || '', text: ownText(j.textContent) }))\\n  .filter(h => h.text.length >= 30)\\n  .sort((a, b) => b.date - a.date)\\n  .slice(0, 3)\\n  .map((h, n) => `--- Échange ${n + 1} (${h.date.toISOString().slice(0, 10)}, objet : ${h.subject}) ---\\\\n${h.text.slice(0, 700)}`)\\n  .join('\\\\n\\\\n');\\n\\nconst body = String(src.text || '').trim().slice(0, 4000);\\nconst prompt = [\\n  'MAIL REÇU',\\n  `De : ${src.from_name ? src.from_name + ' ' : ''}<${src.from_address}>`,\\n  `Objet : ${src.subject}`,\\n  `Date : ${src.date}`,\\n  `Résumé (assistant de tri) : ${src.resume || ''}`,\\n  '',\\n  'Contenu :',\\n  body || '(message sans texte)',\\n  '',\\n  'HISTORIQUE : tes dernières réponses à cet interlocuteur (de la plus récente à la plus ancienne)',\\n  history || \\"(aucun échange précédent trouvé : vouvoie par défaut)\\",\\n  '',\\n  'Rédige le brouillon de réponse.'\\n].join('\\\\n');\\n\\nreturn [{ json: { prompt, historyCount: history ? history.split('--- Échange ').length - 1 : 0 } }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[520,0],"id":"a1000000-0000-4000-8000-000000000003","name":"Assembler le contexte"},{"parameters":{"promptType":"define","text":"={{ $json.prompt }}","messages":{"messageValues":[{"type":"SystemMessagePromptTemplate","message":"Tu rédiges des BROUILLONS de réponses d'e-mails pour la boîte administrative d'EBANISTA (menuiserie / ébénisterie sur mesure). Cette boîte sert au secrétariat, à la comptabilité, aux ressources humaines et aux échanges avec les clients et les fournisseurs. La personne qui la gère relira et modifiera chaque brouillon avant de l'envoyer : tu écris à sa place, dans son style.\\n\\nRéponds UNIQUEMENT avec le corps du message : pas d'objet, pas de commentaire, pas de guillemets, pas de balises.\\n\\nSTYLE (tiré des mails envoyés depuis cette boîte) :\\n- Vouvoiement quasi systématique, ton poli, professionnel et courtois, sans familiarité. Tutoie uniquement si l'historique de ses échanges avec cette personne montre qu'elle la tutoie.\\n- Salutation : \\"Bonjour,\\" ou \\"Bonjour Prénom,\\" ; \\"Bonjour Madame Nom,\\" / \\"Bonjour Monsieur Nom,\\" avec un interlocuteur formel. Mets un prénom ou un nom seulement si tu en es sûr.\\n- Phrases complètes et claires, paragraphes courts (3 à 8 lignes en général). Formules typiques : \\"Je reviens vers vous concernant …\\", \\"Merci pour votre retour.\\", \\"Merci beaucoup pour l'envoi de …\\", \\"Vous trouverez en pièce jointe …\\", \\"Je vous mets … en pièce jointe.\\".\\n- Demandes précises : \\"Pourriez-vous …\\", \\"Serait-il possible de …\\". Si plusieurs points, une liste à puces.\\n- Avant la fin : \\"Merci d'avance pour votre retour.\\" ou \\"Je vous remercie par avance pour votre retour.\\"\\n- Formule de fin : \\"Cordialement,\\" ou \\"Bien cordialement,\\", parfois \\"Bonne journée,\\" / \\"Belle journée,\\".\\n- Signature : écris exactement [À COMPLÉTER : signature] sur la dernière ligne, sous la formule de fin.\\n- Réclamation, litige ou retard (facture erronée, résiliation, livraison manquante) : ton ferme, calme et factuel ; rappelle les dates, références et faits qui figurent dans le mail reçu ; demande clairement ce qui est attendu et dans quel délai si le mail le permet.\\n\\nRÈGLES STRICTES :\\n- N'invente JAMAIS un montant, un nombre d'heures, une date, un délai, un numéro de contrat ou de dossier, une référence, une quantité ni un engagement. Si une information nécessaire manque, écris [À COMPLÉTER : ce qu'il faut préciser] à l'endroit voulu.\\n- Les DÉCISIONS ne sont jamais à ta charge : accepter ou refuser une offre, valider un devis, passer ou annuler une commande, payer, fixer une date, accorder un geste commercial, valider une demande d'un salarié. N'écris jamais \\"oui\\", \\"c'est d'accord\\", \\"je confirme\\" ou \\"nous validons\\" à sa place. Écris [À COMPLÉTER : décision à prendre (ce qu'il faut trancher)] ou une réponse neutre (accuser réception, demander une précision, dire que tu reviens vers l'interlocuteur).\\n- N'ajoute AUCUNE précision (références, dimensions, quantités, noms de personnes, détails de paie ou de contrat) qui n'est pas dans le mail reçu, même si elle apparaît dans l'historique : l'historique ne sert qu'à choisir le ton (tu / vous), la salutation et la formule de fin. Ne reprends jamais d'informations personnelles d'un ancien échange.\\n- Sujets sensibles (paie, ressources humaines, rupture de contrat, litiges juridiques) : reste neutre et prudent, n'engage pas l'entreprise, laisse [À COMPLÉTER] pour toute information ou décision.\\n- Réponds à toutes les questions posées dans le mail reçu, point par point si nécessaire.\\n- Écris en français, sauf si l'interlocuteur écrit dans une autre langue : réponds alors dans sa langue.\\n- Ne cite pas l'historique et ne recopie pas le mail reçu."}]},"batching":{}},"type":"@n8n/n8n-nodes-langchain.chainLlm","typeVersion":1.9,"position":[780,0],"id":"a1000000-0000-4000-8000-000000000004","name":"Rédiger le brouillon"},{"parameters":{"model":{"__rl":true,"mode":"list","value":"claude-sonnet-4-6","cachedResultName":"Claude Sonnet 4.6"},"options":{"temperature":0.4}},"type":"@n8n/n8n-nodes-langchain.lmChatAnthropic","typeVersion":1.5,"position":[820,220],"id":"a1000000-0000-4000-8000-000000000005","name":"Modèle Claude (brouillon)","credentials":{"anthropicApi":{"id":"FRxZizEr7zCaHHZp","name":"Claude API"}}},{"parameters":{"jsCode":"// Compose un e-mail RFC822 (réponse) à enregistrer dans le dossier Brouillons\\nconst src = $('Entrée sous-workflow').first().json;\\nconst draft = String($input.first().json.text || '').trim();\\nif (!draft) throw new Error('Brouillon vide renvoyé par le modèle');\\n\\nconst MY = { name: 'Ebanista', addr: 'contact@ebanista.fr' };\\nconst CRLF = '\\\\r\\\\n';\\nconst b64 = (s) => Buffer.from(s, 'utf8').toString('base64');\\nconst isAscii = (s) => /^[\\\\x20-\\\\x7e]*$/.test(s);\\n\\n// en-tête non ASCII -> mots encodés (RFC 2047), découpés en petits morceaux\\nconst encodeHeader = (s) => {\\n  if (isAscii(s)) return s;\\n  const chars = Array.from(s), parts = [];\\n  for (let i = 0; i < chars.length; i += 10) parts.push(`=?UTF-8?B?${b64(chars.slice(i, i + 10).join(''))}?=`);\\n  return parts.join(CRLF + ' ');\\n};\\nconst displayName = (name) => {\\n  if (!name) return '';\\n  // nom non ASCII : un seul mot encodé (le découper en plusieurs mots encodés le coupe à l'affichage)\\n  if (!isAscii(name)) return `=?UTF-8?B?${b64(name)}?=`;\\n  return /[^\\\\w .'-]/.test(name) ? `\\"${name.replace(/([\\"\\\\\\\\])/g, '\\\\\\\\$1')}\\"` : name;\\n};\\n\\nlet subject = String(src.subject || '').trim();\\nwhile (/^(re|ré)\\\\s*:\\\\s*/i.test(subject)) subject = subject.replace(/^(re|ré)\\\\s*:\\\\s*/i, '');\\nsubject = 'Re: ' + subject;\\n\\nconst origId = src.message_id ? (String(src.message_id).startsWith('<') ? src.message_id : `<${src.message_id}>`) : '';\\nconst when = src.date ? new Date(src.date).toLocaleString('fr-FR', { timeZone: 'Europe/Paris', dateStyle: 'long', timeStyle: 'short' }) : '';\\nconst who = (src.from_name ? src.from_name + ' ' : '') + `<${src.from_address}>`;\\nconst quoted = String(src.text || '').replace(/\\\\r/g, '').trim().slice(0, 3000).split('\\\\n').map(l => '> ' + l).join('\\\\n');\\nconst text = `${draft}\\\\n\\\\n\\\\nLe ${when}, ${who} a écrit :\\\\n${quoted}\\\\n`;\\n\\nconst headers = [\\n  `From: ${displayName(MY.name)} <${MY.addr}>`,\\n  `To: ${src.from_name ? displayName(src.from_name) + ' ' : ''}<${src.from_address}>`,\\n  `Subject: ${encodeHeader(subject)}`,\\n  `Date: ${new Date().toUTCString().replace('GMT', '+0000')}`,\\n  `Message-ID: <draft-${Date.now()}-${Math.random().toString(36).slice(2, 10)}@ebanista.fr>`,\\n  ...(origId ? [`In-Reply-To: ${origId}`, `References: ${origId}`] : []),\\n  'MIME-Version: 1.0',\\n  'Content-Type: text/plain; charset=UTF-8',\\n  'Content-Transfer-Encoding: base64',\\n];\\nconst bodyB64 = b64(text.replace(/\\\\n/g, CRLF)).replace(/(.{76})/g, '$1' + CRLF);\\n\\nreturn [{ json: { rfc822: headers.join(CRLF) + CRLF + CRLF + bodyB64 + CRLF, subject, draftPreview: draft } }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1100,0],"id":"a1000000-0000-4000-8000-000000000006","name":"Composer le brouillon"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"createDraft","destinationMailbox":{"__rl":true,"mode":"path","value":"Drafts"},"inputFormat":"rfc822","rfc822":"={{ $json.rfc822 }}"},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[1360,0],"id":"a1000000-0000-4000-8000-000000000007","name":"Enregistrer dans Brouillons","credentials":{"imap":{"id":"nFnyy1qJ60BZTKsw","name":"IMAP - contact@ebanista.fr"}}}]	{"Entrée sous-workflow":{"main":[[{"node":"Retrouver mes réponses précédentes","type":"main","index":0}]]},"Retrouver mes réponses précédentes":{"main":[[{"node":"Assembler le contexte","type":"main","index":0}]]},"Assembler le contexte":{"main":[[{"node":"Rédiger le brouillon","type":"main","index":0}]]},"Modèle Claude (brouillon)":{"ai_languageModel":[[{"node":"Rédiger le brouillon","type":"ai_languageModel","index":0}]]},"Rédiger le brouillon":{"main":[[{"node":"Composer le brouillon","type":"main","index":0}]]},"Composer le brouillon":{"main":[[{"node":"Enregistrer dans Brouillons","type":"main","index":0}]]}}	\N	f	\N	[]
d7b8972e-f4ed-479d-9f32-241a4b0b30eb	705Af47ZTs7QhMZd	Valentin Caufriez	2026-10-09 19:26:08.757+00	2026-10-09 19:26:08.757+00	[{"parameters":{"inputSource":"passthrough"},"type":"n8n-nodes-base.executeWorkflowTrigger","typeVersion":1.1,"position":[0,0],"id":"a1000000-0000-4000-8000-000000000001","name":"Entrée sous-workflow"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"getEmailsList","mailboxPath":{"__rl":true,"mode":"path","value":"Sent"},"emailDateRange":{"since":"={{ $now.minus({ years: 1 }).toISO() }}"},"emailSearchFilters":{"to":"={{ $json.from_address || 'adresse-introuvable@invalid.invalid' }}"},"limit":40,"includeParts":["textContent"]},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[260,0],"id":"a1000000-0000-4000-8000-000000000002","name":"Retrouver mes réponses précédentes","alwaysOutputData":true,"onError":"continueRegularOutput","credentials":{"imap":{"id":"TkTrXXrbgNbUWRld","name":"IMAP - comptabilite@ebanista.fr"}}},{"parameters":{"jsCode":"// Assemble le prompt : mail reçu + historique des réponses précédentes à ce correspondant\\nconst src = $('Entrée sous-workflow').first().json;\\nconst found = $input.all().map(i => i.json).filter(j => j && j.envelope && !j.error);\\n\\nconst ownText = (t) => String(t || '').replace(/\\\\r/g, '')\\n  .split(/\\\\n(?:>|Le .{5,90} a écrit|De ?:|From:|-----Original|On .{5,90} wrote)/)[0].trim();\\n\\nconst history = found\\n  .map(j => ({ date: new Date(j.envelope.date || 0), subject: j.envelope.subject || '', text: ownText(j.textContent) }))\\n  .filter(h => h.text.length >= 30)\\n  .sort((a, b) => b.date - a.date)\\n  .slice(0, 3)\\n  .map((h, n) => `--- Échange ${n + 1} (${h.date.toISOString().slice(0, 10)}, objet : ${h.subject}) ---\\\\n${h.text.slice(0, 700)}`)\\n  .join('\\\\n\\\\n');\\n\\nconst body = String(src.text || '').trim().slice(0, 4000);\\nconst prompt = [\\n  'MAIL REÇU',\\n  `De : ${src.from_name ? src.from_name + ' ' : ''}<${src.from_address}>`,\\n  `Objet : ${src.subject}`,\\n  `Date : ${src.date}`,\\n  `Résumé (assistant de tri) : ${src.resume || ''}`,\\n  '',\\n  'Contenu :',\\n  body || '(message sans texte)',\\n  '',\\n  'HISTORIQUE : tes dernières réponses à cet interlocuteur (de la plus récente à la plus ancienne)',\\n  history || \\"(aucun échange précédent trouvé : vouvoie par défaut)\\",\\n  '',\\n  'Rédige le brouillon de réponse.'\\n].join('\\\\n');\\n\\nreturn [{ json: { prompt, historyCount: history ? history.split('--- Échange ').length - 1 : 0 } }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[520,0],"id":"a1000000-0000-4000-8000-000000000003","name":"Assembler le contexte"},{"parameters":{"promptType":"define","text":"={{ $json.prompt }}","messages":{"messageValues":[{"type":"SystemMessagePromptTemplate","message":"Tu rédiges des BROUILLONS de réponses d'e-mails pour la boîte administrative d'EBANISTA (menuiserie / ébénisterie sur mesure). Cette boîte sert au secrétariat, à la comptabilité, aux ressources humaines et aux échanges avec les clients et les fournisseurs. La personne qui la gère relira et modifiera chaque brouillon avant de l'envoyer : tu écris à sa place, dans son style.\\n\\nRéponds UNIQUEMENT avec le corps du message : pas d'objet, pas de commentaire, pas de guillemets, pas de balises.\\n\\nSTYLE (tiré des mails envoyés depuis cette boîte) :\\n- Vouvoiement quasi systématique, ton poli, professionnel et courtois, sans familiarité. Tutoie uniquement si l'historique de ses échanges avec cette personne montre qu'elle la tutoie.\\n- Salutation : \\"Bonjour,\\" ou \\"Bonjour Prénom,\\" ; \\"Bonjour Madame Nom,\\" / \\"Bonjour Monsieur Nom,\\" avec un interlocuteur formel. Mets un prénom ou un nom seulement si tu en es sûr.\\n- Phrases complètes et claires, paragraphes courts (3 à 8 lignes en général). Formules typiques : \\"Je reviens vers vous concernant …\\", \\"Merci pour votre retour.\\", \\"Merci beaucoup pour l'envoi de …\\", \\"Vous trouverez en pièce jointe …\\", \\"Je vous mets … en pièce jointe.\\".\\n- Demandes précises : \\"Pourriez-vous …\\", \\"Serait-il possible de …\\". Si plusieurs points, une liste à puces.\\n- Avant la fin : \\"Merci d'avance pour votre retour.\\" ou \\"Je vous remercie par avance pour votre retour.\\"\\n- Formule de fin : \\"Cordialement,\\" ou \\"Bien cordialement,\\", parfois \\"Bonne journée,\\" / \\"Belle journée,\\".\\n- Signature : écris exactement [À COMPLÉTER : signature] sur la dernière ligne, sous la formule de fin.\\n- Réclamation, litige ou retard (facture erronée, résiliation, livraison manquante) : ton ferme, calme et factuel ; rappelle les dates, références et faits qui figurent dans le mail reçu ; demande clairement ce qui est attendu et dans quel délai si le mail le permet.\\n\\nRÈGLES STRICTES :\\n- N'invente JAMAIS un montant, un nombre d'heures, une date, un délai, un numéro de contrat ou de dossier, une référence, une quantité ni un engagement. Si une information nécessaire manque, écris [À COMPLÉTER : ce qu'il faut préciser] à l'endroit voulu.\\n- Les DÉCISIONS ne sont jamais à ta charge : accepter ou refuser une offre, valider un devis, passer ou annuler une commande, payer, fixer une date, accorder un geste commercial, valider une demande d'un salarié. N'écris jamais \\"oui\\", \\"c'est d'accord\\", \\"je confirme\\" ou \\"nous validons\\" à sa place. Écris [À COMPLÉTER : décision à prendre (ce qu'il faut trancher)] ou une réponse neutre (accuser réception, demander une précision, dire que tu reviens vers l'interlocuteur).\\n- N'ajoute AUCUNE précision (références, dimensions, quantités, noms de personnes, détails de paie ou de contrat) qui n'est pas dans le mail reçu, même si elle apparaît dans l'historique : l'historique ne sert qu'à choisir le ton (tu / vous), la salutation et la formule de fin. Ne reprends jamais d'informations personnelles d'un ancien échange.\\n- Sujets sensibles (paie, ressources humaines, rupture de contrat, litiges juridiques) : reste neutre et prudent, n'engage pas l'entreprise, laisse [À COMPLÉTER] pour toute information ou décision.\\n- Réponds à toutes les questions posées dans le mail reçu, point par point si nécessaire.\\n- Écris en français, sauf si l'interlocuteur écrit dans une autre langue : réponds alors dans sa langue.\\n- Ne cite pas l'historique et ne recopie pas le mail reçu."}]},"batching":{}},"type":"@n8n/n8n-nodes-langchain.chainLlm","typeVersion":1.9,"position":[780,0],"id":"a1000000-0000-4000-8000-000000000004","name":"Rédiger le brouillon"},{"parameters":{"model":{"__rl":true,"mode":"list","value":"claude-sonnet-4-6","cachedResultName":"Claude Sonnet 4.6"},"options":{"temperature":0.4}},"type":"@n8n/n8n-nodes-langchain.lmChatAnthropic","typeVersion":1.5,"position":[820,220],"id":"a1000000-0000-4000-8000-000000000005","name":"Modèle Claude (brouillon)","credentials":{"anthropicApi":{"id":"FRxZizEr7zCaHHZp","name":"Claude API"}}},{"parameters":{"jsCode":"// Compose un e-mail RFC822 (réponse) à enregistrer dans le dossier Brouillons\\nconst src = $('Entrée sous-workflow').first().json;\\nconst draft = String($input.first().json.text || '').trim();\\nif (!draft) throw new Error('Brouillon vide renvoyé par le modèle');\\n\\nconst MY = { name: 'Ebanista', addr: 'comptabilite@ebanista.fr' };\\nconst CRLF = '\\\\r\\\\n';\\nconst b64 = (s) => Buffer.from(s, 'utf8').toString('base64');\\nconst isAscii = (s) => /^[\\\\x20-\\\\x7e]*$/.test(s);\\n\\n// en-tête non ASCII -> mots encodés (RFC 2047), découpés en petits morceaux\\nconst encodeHeader = (s) => {\\n  if (isAscii(s)) return s;\\n  const chars = Array.from(s), parts = [];\\n  for (let i = 0; i < chars.length; i += 10) parts.push(`=?UTF-8?B?${b64(chars.slice(i, i + 10).join(''))}?=`);\\n  return parts.join(CRLF + ' ');\\n};\\nconst displayName = (name) => {\\n  if (!name) return '';\\n  // nom non ASCII : un seul mot encodé (le découper en plusieurs mots encodés le coupe à l'affichage)\\n  if (!isAscii(name)) return `=?UTF-8?B?${b64(name)}?=`;\\n  return /[^\\\\w .'-]/.test(name) ? `\\"${name.replace(/([\\"\\\\\\\\])/g, '\\\\\\\\$1')}\\"` : name;\\n};\\n\\nlet subject = String(src.subject || '').trim();\\nwhile (/^(re|ré)\\\\s*:\\\\s*/i.test(subject)) subject = subject.replace(/^(re|ré)\\\\s*:\\\\s*/i, '');\\nsubject = 'Re: ' + subject;\\n\\nconst origId = src.message_id ? (String(src.message_id).startsWith('<') ? src.message_id : `<${src.message_id}>`) : '';\\nconst when = src.date ? new Date(src.date).toLocaleString('fr-FR', { timeZone: 'Europe/Paris', dateStyle: 'long', timeStyle: 'short' }) : '';\\nconst who = (src.from_name ? src.from_name + ' ' : '') + `<${src.from_address}>`;\\nconst quoted = String(src.text || '').replace(/\\\\r/g, '').trim().slice(0, 3000).split('\\\\n').map(l => '> ' + l).join('\\\\n');\\nconst text = `${draft}\\\\n\\\\n\\\\nLe ${when}, ${who} a écrit :\\\\n${quoted}\\\\n`;\\n\\nconst headers = [\\n  `From: ${displayName(MY.name)} <${MY.addr}>`,\\n  `To: ${src.from_name ? displayName(src.from_name) + ' ' : ''}<${src.from_address}>`,\\n  `Subject: ${encodeHeader(subject)}`,\\n  `Date: ${new Date().toUTCString().replace('GMT', '+0000')}`,\\n  `Message-ID: <draft-${Date.now()}-${Math.random().toString(36).slice(2, 10)}@ebanista.fr>`,\\n  ...(origId ? [`In-Reply-To: ${origId}`, `References: ${origId}`] : []),\\n  'MIME-Version: 1.0',\\n  'Content-Type: text/plain; charset=UTF-8',\\n  'Content-Transfer-Encoding: base64',\\n];\\nconst bodyB64 = b64(text.replace(/\\\\n/g, CRLF)).replace(/(.{76})/g, '$1' + CRLF);\\n\\nreturn [{ json: { rfc822: headers.join(CRLF) + CRLF + CRLF + bodyB64 + CRLF, subject, draftPreview: draft } }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1100,0],"id":"a1000000-0000-4000-8000-000000000006","name":"Composer le brouillon"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"createDraft","destinationMailbox":{"__rl":true,"mode":"path","value":"Drafts"},"inputFormat":"rfc822","rfc822":"={{ $json.rfc822 }}"},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[1360,0],"id":"a1000000-0000-4000-8000-000000000007","name":"Enregistrer dans Brouillons","credentials":{"imap":{"id":"TkTrXXrbgNbUWRld","name":"IMAP - comptabilite@ebanista.fr"}}}]	{"Entrée sous-workflow":{"main":[[{"node":"Retrouver mes réponses précédentes","type":"main","index":0}]]},"Retrouver mes réponses précédentes":{"main":[[{"node":"Assembler le contexte","type":"main","index":0}]]},"Assembler le contexte":{"main":[[{"node":"Rédiger le brouillon","type":"main","index":0}]]},"Modèle Claude (brouillon)":{"ai_languageModel":[[{"node":"Rédiger le brouillon","type":"ai_languageModel","index":0}]]},"Rédiger le brouillon":{"main":[[{"node":"Composer le brouillon","type":"main","index":0}]]},"Composer le brouillon":{"main":[[{"node":"Enregistrer dans Brouillons","type":"main","index":0}]]}}	\N	f	\N	[]
f1d63dc6-7fd2-4cc4-943b-02c1383249a2	wNqeTKj68eF0lqFJ	Valentin Caufriez	2026-10-09 20:35:55.994+00	2026-10-09 20:35:55.994+00	[{"parameters":{"httpMethod":"POST","path":"assistant-mails-0e623b6c920aa52f22bb7772","authentication":"headerAuth","responseMode":"lastNode","options":{}},"type":"n8n-nodes-base.webhook","typeVersion":2,"position":[0,0],"id":"b3043dde-80ab-4a28-bf9d-079dfd7c96ef","name":"Webhook Telegram","credentials":{"httpHeaderAuth":{"id":"86dpp3Vg9wZOdnpT","name":"Pont Telegram (secret)"}},"webhookId":"b3aefde1-f923-49a8-ae02-67f177128485"},{"parameters":{"jsCode":"// Réception d'une mise à jour Telegram : filtre l'expéditeur, évite les doublons, retrouve la conversation en cours\\nconst ALLOWED = 8848139246;\\nconst upd = $input.first().json.body || {};\\nconst sd = $getWorkflowStaticData('global');\\nsd.seen = sd.seen || [];\\nsd.sessions = sd.sessions || {};\\n\\nconst msg = upd.message, cb = upd.callback_query;\\nconst from = (msg && msg.from) || (cb && cb.from) || {};\\nconst chat = (msg && msg.chat) || (cb && cb.message && cb.message.chat) || {};\\n\\n// seul le compte de Valentin est autorisé : tout autre expéditeur est ignoré sans réponse\\nif (Number(from.id) !== ALLOWED || Number(chat.id) !== ALLOWED) return [{ json: { route: 'ignore' } }];\\n\\n// une même mise à jour n'est jamais traitée deux fois\\nif (upd.update_id !== undefined) {\\n  if (sd.seen.includes(upd.update_id)) return [{ json: { route: 'ignore' } }];\\n  sd.seen.push(upd.update_id);\\n  if (sd.seen.length > 100) sd.seen = sd.seen.slice(-100);\\n}\\n\\nconst key = String(chat.id);\\nlet s = sd.sessions[key];\\nif (s && Date.now() - (s.updated || 0) > 45 * 60 * 1000) { delete sd.sessions[key]; s = undefined; } // conversation expirée après 45 min\\n\\nlet route = 'message', text = '', pick = 0;\\nif (cb) route = 'callback';\\nelse if (msg && msg.text && s && s.state === 'reply_pick' && s.mail_candidates && /^\\\\s*[1-9]\\\\s*$/.test(msg.text)) { route = 'reply_choose'; pick = Number(msg.text.trim()); }\\nelse if (msg && msg.text) route = 'claude';\\nelse text = \\"Je ne sais traiter que du texte pour l'instant. Écrivez-moi (ou dictez avec le clavier de votre téléphone) à qui écrire, le sujet et ce qu'il faut dire.\\";\\n\\nreturn [{ json: {\\n  route, text, pick, chat_id: chat.id, update_id: upd.update_id,\\n  user_text: msg ? (msg.text || '') : '',\\n  cb_data: cb ? (cb.data || '') : '', cb_id: cb ? cb.id : '',\\n  session: s || null,\\n} }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[250,0],"id":"99722a57-f703-41b9-ab67-4bfa8ab07a76","name":"Normaliser la mise à jour"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"e39c0628-d8ee-4975-81c7-8f41815a93d5","leftValue":"={{ $json.route }}","rightValue":"callback","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[500,0],"id":"b543d024-91e6-4ab3-b9e3-b22b0286b79d","name":"Bouton ?"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"2a4ed0cd-f6d1-49d7-b286-a89ab94d5d5f","leftValue":"={{ $json.route }}","rightValue":"claude","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[500,400],"id":"575eedd5-2d6d-4ec7-a9c3-936e46b15c52","name":"Demande à Claude ?"},{"parameters":{"chatId":"={{ $json.chat_id }}","text":"={{ String($json.text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') }}","additionalFields":{"appendAttribution":false,"parse_mode":"HTML"}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[2400,400],"id":"52fb5149-bd9d-4fd4-a266-d879016f0c83","name":"Message texte","credentials":{"telegramApi":{"id":"duvmoy6UkxnbnBdr","name":"Ebanista Mails"}},"webhookId":"04fe3fea-0d69-4ea4-b0fd-6a328d